public enum RemoteInputKind { MouseMove, MouseDown, MouseUp, Wheel, KeyDown, KeyUp, ReleaseAll }
public enum RemoteMouseButton { Left, Right, Middle }
public sealed record RemoteInputEvent(RemoteInputKind Kind, double X = 0, double Y = 0,
    RemoteMouseButton Button = RemoteMouseButton.Left, int WheelDelta = 0, int ScanCode = 0, bool Extended = false);
public sealed record RemoteInputResult(bool Accepted, string Message);
public readonly record struct InputScreenPoint(int X, int Y, int AbsoluteX, int AbsoluteY);
public readonly record struct InputMonitorBounds(int Left, int Top, int Width, int Height);

public interface IRemoteInputInjector
{
    RemoteInputResult Inject(RemoteInputEvent input);
    RemoteInputResult ReleaseAll();
}

public static class InputCoordinates
{
    public static InputScreenPoint Map(double x, double y, int primaryWidth, int primaryHeight,
        int virtualLeft, int virtualTop, int virtualWidth, int virtualHeight) =>
        Map(x, y, new(0, 0, primaryWidth, primaryHeight), virtualLeft, virtualTop, virtualWidth, virtualHeight);

    public static InputScreenPoint Map(double x, double y, InputMonitorBounds source,
        int virtualLeft, int virtualTop, int virtualWidth, int virtualHeight)
    {
        if (!double.IsFinite(x) || !double.IsFinite(y) || x is < 0 or > 1 || y is < 0 or > 1 ||
            source.Width < 1 || source.Height < 1 || virtualWidth < 1 || virtualHeight < 1)
            throw new ArgumentOutOfRangeException(nameof(x), "Expected normalized coordinates and a valid desktop rectangle.");
        var px = source.Left + (int)Math.Round(x * (source.Width - 1));
        var py = source.Top + (int)Math.Round(y * (source.Height - 1));
        var absoluteX = (int)Math.Round((px - virtualLeft) * 65535d / Math.Max(1, virtualWidth - 1));
        var absoluteY = (int)Math.Round((py - virtualTop) * 65535d / Math.Max(1, virtualHeight - 1));
        return new(px, py, Math.Clamp(absoluteX, 0, 65535), Math.Clamp(absoluteY, 0, 65535));
    }

    public static (double X, double Y) Normalize(int x, int y, int width, int height) =>
        (Math.Clamp(x / (double)Math.Max(1, width - 1), 0, 1), Math.Clamp(y / (double)Math.Max(1, height - 1), 0, 1));

    public static RemoteInputEvent? MapFromVideo(RemoteInputEvent input, int videoWidth, int videoHeight, int sourceWidth, int sourceHeight)
    {
        if (input.Kind is RemoteInputKind.KeyDown or RemoteInputKind.KeyUp or RemoteInputKind.ReleaseAll) return input;
        if (videoWidth <= 0 || videoHeight <= 0 || sourceWidth <= 0 || sourceHeight <= 0 ||
            !double.IsFinite(input.X) || !double.IsFinite(input.Y) || input.X is < 0 or > 1 || input.Y is < 0 or > 1)
            throw new ArgumentOutOfRangeException(nameof(input), "Invalid video/content geometry.");
        var scale = Math.Min(videoWidth / (double)sourceWidth, videoHeight / (double)sourceHeight);
        var width = (int)Math.Round(sourceWidth * scale);
        var height = (int)Math.Round(sourceHeight * scale);
        var left = (videoWidth - width) / 2;
        var top = (videoHeight - height) / 2;
        var x = input.X * (videoWidth - 1);
        var y = input.Y * (videoHeight - 1);
        if (x < left || y < top || x > left + width - 1 || y > top + height - 1)
            return input.Kind == RemoteInputKind.MouseUp ? new(RemoteInputKind.ReleaseAll) : null;
        return input with { X = (x - left) / Math.Max(1, width - 1), Y = (y - top) / Math.Max(1, height - 1) };
    }
}

sealed record InputRequest(long Sequence, bool? Enable = null, RemoteInputEvent? Input = null);
sealed record InputReply(long Sequence, bool Accepted, string Message);

static class InputProtocol
{
    const int MaximumMessageBytes = 4096;

    public static async Task WriteAsync<T>(NetworkStream stream, T message, CancellationToken token)
    {
        var payload = JsonSerializer.SerializeToUtf8Bytes(message);
        if (payload.Length > MaximumMessageBytes) throw new InvalidDataException("Input message exceeds 4096 bytes.");
        var bytes = new byte[payload.Length + 4];
        BinaryPrimitives.WriteInt32LittleEndian(bytes, payload.Length);
        payload.CopyTo(bytes, 4);
        await stream.WriteAsync(bytes, token).ConfigureAwait(false);
    }

    public static async Task<T> ReadAsync<T>(NetworkStream stream, CancellationToken token)
    {
        var header = new byte[4];
        await stream.ReadExactlyAsync(header, token).ConfigureAwait(false);
        var length = BinaryPrimitives.ReadInt32LittleEndian(header);
        if (length is <= 0 or > MaximumMessageBytes) throw new InvalidDataException("Invalid input message length.");
        var bytes = new byte[length];
        await stream.ReadExactlyAsync(bytes, token).ConfigureAwait(false);
        return JsonSerializer.Deserialize<T>(bytes) ?? throw new InvalidDataException("Empty input message.");
    }

    public static void Log(string operation, Exception? error = null) => Console.Error.WriteLine($"[Input] {operation}{(error is null ? "" : $": {error}")}");
}

public sealed class RemoteInputServer : IDisposable
{
    readonly IRemoteInputInjector injector;
    readonly TcpListener listener;
    readonly CancellationTokenSource stop = new();
    readonly Task worker;
    int disposed;
    public IPEndPoint Endpoint => (IPEndPoint)listener.LocalEndpoint;
    public event Action<Exception>? Failed;

    public RemoteInputServer(IRemoteInputInjector injector, int port = 0)
    {
        this.injector = injector;
        listener = new(IPAddress.Loopback, port);
        listener.Start(1);
        worker = Task.Run(RunAsync);
    }

    async Task RunAsync()
    {
        try
        {
            while (!stop.IsCancellationRequested)
            {
                using var peer = await listener.AcceptTcpClientAsync(stop.Token).ConfigureAwait(false);
                await ServePeerAsync(injector, peer, stop.Token, Report);
            }
        }
        catch (OperationCanceledException) when (stop.IsCancellationRequested) { InputProtocol.Log("Input listener stopped."); }
        catch (Exception error) { Report(error); }
    }

    internal static async Task ServePeerAsync(IRemoteInputInjector injector, TcpClient peer, CancellationToken token, Action<Exception>? failure = null)
    {
        peer.NoDelay = true;
        var stream = peer.GetStream();
        var enabled = false;
        long previousSequence = 0;
        try
        {
            while (!token.IsCancellationRequested)
            {
                var request = await InputProtocol.ReadAsync<InputRequest>(stream, token).ConfigureAwait(false);
                if (request.Sequence != previousSequence + 1) throw new InvalidDataException("Input sequence is not contiguous.");
                previousSequence = request.Sequence;
                RemoteInputResult result;
                if (request.Enable is { } enable)
                {
                    if (request.Input is not null) throw new InvalidDataException("Input enable and event are mutually exclusive.");
                    result = enable ? new(true, "Input forwarding enabled.") : injector.ReleaseAll();
                    enabled = enable;
                }
                else if (request.Input is null) result = new(false, "No input event supplied.");
                else if (!enabled) result = new(false, "Input forwarding is disabled.");
                else result = injector.Inject(request.Input);
                await InputProtocol.WriteAsync(stream, new InputReply(request.Sequence, result.Accepted, result.Message), token).ConfigureAwait(false);
            }
        }
        catch (EndOfStreamException) { InputProtocol.Log("Controller disconnected; releasing held input."); }
        catch (OperationCanceledException) when (token.IsCancellationRequested) { InputProtocol.Log("Input peer stopped."); }
        catch (Exception error) { if (failure != null) failure(error); else InputProtocol.Log("Input peer failed", error); }
        finally
        {
            var released = injector.ReleaseAll();
            if (!released.Accepted) InputProtocol.Log(released.Message);
        }
    }

    void Report(Exception error)
    {
        InputProtocol.Log("Input receiver failed", error);
        try { Failed?.Invoke(error); }
        catch (Exception callbackError) { InputProtocol.Log("Input error callback failed", callbackError); }
    }

    public void Dispose()
    {
        if (Interlocked.Exchange(ref disposed, 1) != 0) return;
        stop.Cancel();
        listener.Stop();
        if (!worker.Wait(2000)) InputProtocol.Log("Input receiver has not stopped within 2 seconds.");
        else stop.Dispose();
    }
}

public sealed class RemoteInputClient : IDisposable
{
    readonly TcpClient connection;
    readonly NetworkStream stream;
    readonly SemaphoreSlim gate = new(1, 1);
    readonly CancellationTokenSource stop = new();
    long sequence;
    long enableRevision;
    int enabled, disposed;
    public bool Enabled => Volatile.Read(ref enabled) != 0;

    internal RemoteInputClient(TcpClient connection) { this.connection = connection; stream = connection.GetStream(); }

    public static async Task<RemoteInputClient> ConnectAsync(IPEndPoint endpoint, CancellationToken token = default)
    {
        var connection = new TcpClient { NoDelay = true };
        try
        {
            await connection.ConnectAsync(endpoint, token).ConfigureAwait(false);
            return new(connection);
        }
        catch { connection.Dispose(); throw; }
    }

    public async Task<RemoteInputResult> SetEnabledAsync(bool value, CancellationToken token = default)
    {
        var revision = Interlocked.Increment(ref enableRevision);
        if (!value) Volatile.Write(ref enabled, 0);
        var result = await ExchangeAsync(value, null, token).ConfigureAwait(false);
        if (revision == Interlocked.Read(ref enableRevision)) Volatile.Write(ref enabled, value && result.Accepted ? 1 : 0);
        return result;
    }

    public Task<RemoteInputResult> SendAsync(RemoteInputEvent input, CancellationToken token = default) =>
        !Enabled ? Task.FromResult(new RemoteInputResult(false, "Input forwarding is disabled.")) : ExchangeAsync(null, input, token);

    async Task<RemoteInputResult> ExchangeAsync(bool? enable, RemoteInputEvent? input, CancellationToken token)
    {
        ObjectDisposedException.ThrowIf(Volatile.Read(ref disposed) != 0, this);
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(stop.Token, token);
        await gate.WaitAsync(linked.Token).ConfigureAwait(false);
        try
        {
            if (input is not null && !Enabled) return new(false, "Input forwarding is disabled.");
            var current = ++sequence;
            await InputProtocol.WriteAsync(stream, new InputRequest(current, enable, input), linked.Token).ConfigureAwait(false);
            var reply = await InputProtocol.ReadAsync<InputReply>(stream, linked.Token).ConfigureAwait(false);
            if (reply.Sequence != current) throw new InvalidDataException("Input reply sequence mismatch.");
            return new(reply.Accepted, reply.Message);
        }
        catch (Exception error)
        {
            InputProtocol.Log("Input connection failed; closing it to release held input", error);
            Volatile.Write(ref enabled, 0);
            connection.Close();
            throw;
        }
        finally { gate.Release(); }
    }

    public void Dispose()
    {
        if (Interlocked.Exchange(ref disposed, 1) != 0) return;
        Volatile.Write(ref enabled, 0);
        stop.Cancel();
        connection.Dispose();
        // Connection closure makes the controlled endpoint release every key/button even on abrupt disconnect.
    }
}

public sealed class Win32InputInjector : IRemoteInputInjector, IDisposable
{
    public const nuint InjectionMarker = 0x46524449;
    readonly ConcurrentDictionary<nint, byte> controllers = new();
    readonly HashSet<(int ScanCode, bool Extended)> keys = new();
    readonly HashSet<RemoteMouseButton> buttons = new();
    readonly object gate = new();
    readonly Func<InputMonitorBounds> sourceMonitor;
    public Win32InputInjector(Func<InputMonitorBounds>? sourceMonitor = null) => this.sourceMonitor = sourceMonitor ?? ReadPrimaryMonitor;
    public void RegisterControllerWindow(nint hwnd) { if (hwnd != 0) controllers[hwnd] = 0; }
    public void UnregisterControllerWindow(nint hwnd) => controllers.TryRemove(hwnd, out _);

    public RemoteInputResult Inject(RemoteInputEvent input)
    {
        lock (gate)
        {
            if (input.Kind == RemoteInputKind.ReleaseAll) return ReleaseAll();
            if (input.Kind is RemoteInputKind.KeyDown or RemoteInputKind.KeyUp)
            {
                if (input.ScanCode is <= 0 or > ushort.MaxValue) return new(false, "Invalid keyboard scan code.");
                if (input.Kind == RemoteInputKind.KeyUp && keys.Contains((input.ScanCode, input.Extended)))
                    return ReleaseKey(input.ScanCode, input.Extended);
                if (IsController(GetForegroundWindow())) return new(false, "Keyboard refused: the foreground window belongs to the local controller. A shared desktop cannot be both controller focus and remote keyboard target.");
                var result = Insert(Key(input.ScanCode, input.Extended, input.Kind == RemoteInputKind.KeyUp));
                if (result.Accepted && input.Kind == RemoteInputKind.KeyDown) keys.Add((input.ScanCode, input.Extended));
                return result;
            }
            if (input.Kind is not (RemoteInputKind.MouseMove or RemoteInputKind.MouseDown or RemoteInputKind.MouseUp or RemoteInputKind.Wheel))
                return new(false, "Unknown input event.");
            if (!Enum.IsDefined(input.Button) || input.WheelDelta is < -12000 or > 12000)
                return new(false, "Invalid mouse button or wheel delta.");
            if (input.Kind == RemoteInputKind.MouseUp && buttons.Contains(input.Button)) return ReleaseButton(input.Button);
            InputScreenPoint point;
            try
            {
                point = InputCoordinates.Map(input.X, input.Y, sourceMonitor(),
                    GetSystemMetrics(76), GetSystemMetrics(77), GetSystemMetrics(78), GetSystemMetrics(79));
            }
            catch (ArgumentOutOfRangeException error) { InputProtocol.Log("Mouse coordinate rejected", error); return new(false, error.Message); }
            if (IsController(WindowFromPoint(new() { X = point.X, Y = point.Y })))
                return new(false, "Pointer refused: the target is a local controller/overlay window. Move the controller away from this target, or use a separate desktop/machine.");
            var moved = Insert(Mouse(0x0001 | 0x8000 | 0x4000, point.AbsoluteX, point.AbsoluteY));
            if (!moved.Accepted || input.Kind == RemoteInputKind.MouseMove) return moved;
            if (input.Kind == RemoteInputKind.Wheel) return Insert(Mouse(0x0800, data: unchecked((uint)input.WheelDelta)));
            var mouseResult = Insert(Mouse(ButtonFlag(input.Button, input.Kind == RemoteInputKind.MouseUp)));
            if (mouseResult.Accepted && input.Kind == RemoteInputKind.MouseDown) buttons.Add(input.Button);
            return mouseResult;
        }
    }

    public static InputMonitorBounds ReadPrimaryMonitor()
    {
        var monitor = MonitorFromPoint(new(), 1);
        var information = new MonitorInformation { Size = (uint)Marshal.SizeOf<MonitorInformation>() };
        if (monitor == 0 || !GetMonitorInfo(monitor, ref information)) throw new Win32Exception(Marshal.GetLastWin32Error(), "Cannot read input target monitor bounds.");
        return new(information.Monitor.Left, information.Monitor.Top,
            information.Monitor.Right - information.Monitor.Left, information.Monitor.Bottom - information.Monitor.Top);
    }

    bool IsController(nint hwnd)
    {
        if (hwnd == 0) return false;
        var root = GetAncestor(hwnd, 2);
        var owner = GetAncestor(hwnd, 3);
        return controllers.Keys.Any(controller => IsWindow(controller) &&
            (hwnd == controller || root == controller || owner == controller || IsChild(controller, hwnd)));
    }

    public RemoteInputResult ReleaseAll()
    {
        lock (gate)
        {
            List<string> failures = new();
            foreach (var key in keys.ToArray())
            {
                var result = ReleaseKey(key.ScanCode, key.Extended);
                if (!result.Accepted) failures.Add(result.Message);
            }
            foreach (var button in buttons.ToArray())
            {
                var result = ReleaseButton(button);
                if (!result.Accepted) failures.Add(result.Message);
            }
            return failures.Count == 0 ? new(true, "Held keys and mouse buttons released.") : new(false, string.Join("; ", failures));
        }
    }

    RemoteInputResult ReleaseKey(int scanCode, bool extended)
    {
        var result = Insert(Key(scanCode, extended, true));
        if (result.Accepted) keys.Remove((scanCode, extended));
        return result;
    }

    RemoteInputResult ReleaseButton(RemoteMouseButton button)
    {
        var result = Insert(Mouse(ButtonFlag(button, true)));
        if (result.Accepted) buttons.Remove(button);
        return result;
    }

    static uint ButtonFlag(RemoteMouseButton button, bool up) => button switch
    {
        RemoteMouseButton.Left => up ? 0x0004u : 0x0002u,
        RemoteMouseButton.Right => up ? 0x0010u : 0x0008u,
        RemoteMouseButton.Middle => up ? 0x0040u : 0x0020u,
        _ => throw new ArgumentOutOfRangeException(nameof(button))
    };

    static NativeInput Mouse(uint flags, int x = 0, int y = 0, uint data = 0) => new()
    { Type = 0, Value = new() { Mouse = new() { X = x, Y = y, Data = data, Flags = flags, Extra = InjectionMarker } } };
    static NativeInput Key(int scanCode, bool extended, bool up) => new()
    { Type = 1, Value = new() { Keyboard = new() { ScanCode = (ushort)scanCode, Flags = 0x0008u | (extended ? 1u : 0u) | (up ? 2u : 0u), Extra = InjectionMarker } } };

    static RemoteInputResult Insert(NativeInput input)
    {
        if (SendInput(1, [input], Marshal.SizeOf<NativeInput>()) == 1) return new(true, "Input injected.");
        var error = new Win32Exception(Marshal.GetLastWin32Error(), "SendInput failed; the destination may have higher integrity or be a secure desktop.");
        InputProtocol.Log("System input injection failed", error);
        return new(false, error.Message);
    }

    public void Dispose()
    {
        var result = ReleaseAll();
        if (!result.Accepted) InputProtocol.Log(result.Message);
    }

    [StructLayout(LayoutKind.Sequential)] struct NativeInput { public uint Type; public InputUnion Value; }
    [StructLayout(LayoutKind.Explicit)] struct InputUnion { [FieldOffset(0)] public MouseInput Mouse; [FieldOffset(0)] public KeyboardInput Keyboard; }
    [StructLayout(LayoutKind.Sequential)] struct MouseInput { public int X, Y; public uint Data, Flags, Time; public nuint Extra; }
    [StructLayout(LayoutKind.Sequential)] struct KeyboardInput { public ushort VirtualKey, ScanCode; public uint Flags, Time; public nuint Extra; }
    [StructLayout(LayoutKind.Sequential)] struct Point { public int X, Y; }
    [StructLayout(LayoutKind.Sequential)] struct Rectangle { public int Left, Top, Right, Bottom; }
    [StructLayout(LayoutKind.Sequential)] struct MonitorInformation { public uint Size; public Rectangle Monitor, Work; public uint Flags; }
    [DllImport("user32.dll", SetLastError = true)] static extern uint SendInput(uint count, NativeInput[] inputs, int size);
    [DllImport("user32.dll")] static extern nint GetForegroundWindow();
    [DllImport("user32.dll")] static extern nint WindowFromPoint(Point point);
    [DllImport("user32.dll")] static extern nint GetAncestor(nint hwnd, uint flags);
    [DllImport("user32.dll")] static extern int GetSystemMetrics(int index);
    [DllImport("user32.dll")] static extern nint MonitorFromPoint(Point point, uint flags);
    [DllImport("user32.dll", EntryPoint = "GetMonitorInfoW", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool GetMonitorInfo(nint monitor, ref MonitorInformation information);
    [DllImport("user32.dll")] [return: MarshalAs(UnmanagedType.Bool)] static extern bool IsWindow(nint hwnd);
    [DllImport("user32.dll")] [return: MarshalAs(UnmanagedType.Bool)] static extern bool IsChild(nint parent, nint child);
}

public sealed class NativeInputSource : IDisposable
{
    readonly nint hwnd;
    readonly SubclassProcedure procedure;
    readonly nuint id;
    static long nextId;
    bool enabled, disposed;
    int heldButtons;
    public event Action<RemoteInputEvent>? Input;
    public event Action? ExitRequested;
    public event Action<Exception>? Failed;

    public NativeInputSource(nint hwnd)
    {
        this.hwnd = hwnd;
        id = (nuint)Interlocked.Increment(ref nextId);
        procedure = WindowProcedure;
        if (!SetWindowSubclass(hwnd, procedure, id, 0)) throw new Win32Exception(Marshal.GetLastWin32Error(), "Cannot attach preview input capture.");
    }

    public void SetEnabled(bool value)
    {
        ObjectDisposedException.ThrowIf(disposed, this);
        enabled = value;
        if (value) SetFocus(hwnd);
        else
        {
            heldButtons = 0;
            if (GetCapture() == hwnd) ReleaseCapture();
        }
    }

    nint WindowProcedure(nint window, uint message, nuint wParam, nint lParam, nuint subclassId, nuint reference)
    {
        try
        {
            // STATIC defaults to HTTRANSPARENT, which bypasses this window's real mouse messages.
            if (enabled && message == 0x0084) return 1;
            if (enabled && GetMessageExtraInfo() != (nint)Win32InputInjector.InjectionMarker)
            {
                if (message is 0x0100 or 0x0104 && wParam == 0x1B)
                {
                    SetEnabled(false);
                    Input?.Invoke(new(RemoteInputKind.ReleaseAll));
                    ExitRequested?.Invoke();
                    return 0;
                }
                if (message is 0x0100 or 0x0101 or 0x0104 or 0x0105)
                {
                    var scanCode = (int)(((long)lParam >> 16) & 0xFF);
                    var extended = (((long)lParam >> 24) & 1) != 0;
                    if (scanCode != 0) Input?.Invoke(new(message is 0x0101 or 0x0105 ? RemoteInputKind.KeyUp : RemoteInputKind.KeyDown,
                        ScanCode: scanCode, Extended: extended));
                    return 0;
                }
                if (message is 0x0200 or 0x0201 or 0x0202 or 0x0204 or 0x0205 or 0x0207 or 0x0208 or 0x020A)
                {
                    if (!GetClientRect(hwnd, out var rect)) throw new Win32Exception(Marshal.GetLastWin32Error());
                    var point = new NativePoint { X = (short)((long)lParam & 0xFFFF), Y = (short)(((long)lParam >> 16) & 0xFFFF) };
                    if (message == 0x020A && !ScreenToClient(hwnd, ref point)) throw new Win32Exception(Marshal.GetLastWin32Error());
                    var normalized = InputCoordinates.Normalize(point.X, point.Y, rect.Right - rect.Left, rect.Bottom - rect.Top);
                    var kind = message switch
                    {
                        0x0200 => RemoteInputKind.MouseMove,
                        0x0201 or 0x0204 or 0x0207 => RemoteInputKind.MouseDown,
                        0x020A => RemoteInputKind.Wheel,
                        _ => RemoteInputKind.MouseUp
                    };
                    var button = message is 0x0204 or 0x0205 ? RemoteMouseButton.Right : message is 0x0207 or 0x0208 ? RemoteMouseButton.Middle : RemoteMouseButton.Left;
                    if (kind == RemoteInputKind.MouseDown) { SetFocus(hwnd); SetCapture(hwnd); heldButtons |= 1 << (int)button; }
                    Input?.Invoke(new(kind, normalized.X, normalized.Y, button, message == 0x020A ? (short)((wParam >> 16) & 0xFFFF) : 0));
                    if (kind == RemoteInputKind.MouseUp)
                    {
                        heldButtons &= ~(1 << (int)button);
                        if (heldButtons == 0 && GetCapture() == hwnd) ReleaseCapture();
                    }
                    return 0;
                }
                if (message is 0x0008 or 0x0215) Input?.Invoke(new(RemoteInputKind.ReleaseAll));
            }
        }
        catch (Exception error)
        {
            InputProtocol.Log("Native input source failed", error);
            try { Failed?.Invoke(error); }
            catch (Exception callbackError) { InputProtocol.Log("Native input error callback failed", callbackError); }
        }
        return DefSubclassProc(window, message, wParam, lParam);
    }

    public void Dispose()
    {
        if (disposed) return;
        SetEnabled(false);
        if (!RemoveWindowSubclass(hwnd, procedure, id)) InputProtocol.Log("Cannot detach preview input capture", new Win32Exception(Marshal.GetLastWin32Error()));
        disposed = true;
    }

    [StructLayout(LayoutKind.Sequential)] struct NativePoint { public int X, Y; }
    [StructLayout(LayoutKind.Sequential)] struct NativeRect { public int Left, Top, Right, Bottom; }
    delegate nint SubclassProcedure(nint hwnd, uint message, nuint wParam, nint lParam, nuint subclassId, nuint reference);
    [DllImport("comctl32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool SetWindowSubclass(nint hwnd, SubclassProcedure callback, nuint id, nuint reference);
    [DllImport("comctl32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool RemoveWindowSubclass(nint hwnd, SubclassProcedure callback, nuint id);
    [DllImport("comctl32.dll")] static extern nint DefSubclassProc(nint hwnd, uint message, nuint wParam, nint lParam);
    [DllImport("user32.dll")] static extern nint SetFocus(nint hwnd);
    [DllImport("user32.dll")] static extern nint SetCapture(nint hwnd);
    [DllImport("user32.dll")] static extern nint GetCapture();
    [DllImport("user32.dll")] [return: MarshalAs(UnmanagedType.Bool)] static extern bool ReleaseCapture();
    [DllImport("user32.dll")] static extern nint GetMessageExtraInfo();
    [DllImport("user32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool GetClientRect(nint hwnd, out NativeRect rect);
    [DllImport("user32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool ScreenToClient(nint hwnd, ref NativePoint point);
}

// Source: FfmpegPresentation.cs
public sealed class ConfirmedVideoView : NativeControlHost
{
    readonly object gate = new();
    readonly AutoResetEvent changed = new(false);
    DecodedPixels? pending;
    NativeInputSource? inputSource;
    Thread? renderThread;
    nint sourceWindow;
    bool stopped, inputEnabled;
    int sourceWidth = 1280, sourceHeight = 720;

    public event Action<long, long>? Presented;
    public event Action<Exception>? Failed;
    public event Action<RemoteInputEvent>? Input;
    public event Action? InputExitRequested;
    public nint SourceWindow => sourceWindow;

    public void SetInputEnabled(bool enabled)
    {
        if (!Dispatcher.UIThread.CheckAccess()) throw new InvalidOperationException("Input mode must change on the UI thread.");
        inputEnabled = enabled;
        inputSource?.SetEnabled(enabled);
    }

    public ConfirmedVideoView()
    {
        HorizontalAlignment = HorizontalAlignment.Center;
        VerticalAlignment = VerticalAlignment.Center;
    }

    public void Submit(DecodedPixels pixels)
    {
        if (pixels.Width is <= 0 or > 8192 || pixels.Height is <= 0 or > 8192 ||
            pixels.Bgra.Length != checked(pixels.Width * pixels.Height * 4))
            throw new ArgumentException("Invalid tightly packed BGRA image.", nameof(pixels));
        lock (gate)
        {
            if (stopped) return;
            // Decoder output owns a fresh immutable array; replacement only discards unrendered output.
            pending = pixels;
            changed.Set();
        }
    }

    protected override Size MeasureOverride(Size availableSize)
    {
        var width = Volatile.Read(ref sourceWidth);
        var height = Volatile.Read(ref sourceHeight);
        var scale = Math.Min(availableSize.Width / width, availableSize.Height / height);
        if (!double.IsFinite(scale)) scale = 1;
        return new(width * Math.Max(0, scale), height * Math.Max(0, scale));
    }

    protected override IPlatformHandle CreateNativeControlCore(IPlatformHandle parent)
    {
        var hwnd = CreateWindowEx(0, "STATIC", "", 0x40000000 | 0x10000000 | 0x04000000,
            0, 0, sourceWidth, sourceHeight, parent.Handle, 0, 0, 0);
        if (hwnd == 0) throw new Win32Exception(Marshal.GetLastWin32Error(), "Cannot create D3D11 presentation window.");
        sourceWindow = hwnd;
        inputSource = new(hwnd);
        inputSource.Input += value => Input?.Invoke(value);
        inputSource.ExitRequested += () => { inputEnabled = false; InputExitRequested?.Invoke(); };
        inputSource.Failed += Report;
        inputSource.SetEnabled(inputEnabled);
        lock (gate)
        {
            if (!stopped)
            {
                renderThread = new(() => Render(hwnd)) { IsBackground = true, Name = "FRD confirmed GPU presentation" };
                renderThread.Start();
            }
        }
        return new PlatformHandle(hwnd, "HWND");
    }

    protected override void DestroyNativeControlCore(IPlatformHandle control)
    {
        inputSource?.Dispose();
        inputSource = null;
        Stop();
        if (control.Handle != 0 && !DestroyWindow(control.Handle))
            Report(new Win32Exception(Marshal.GetLastWin32Error(), "Cannot destroy D3D11 presentation window."));
        sourceWindow = 0;
    }

    public void Stop()
    {
        Thread? thread;
        lock (gate)
        {
            if (stopped) return;
            stopped = true;
            pending = null;
            thread = renderThread;
            changed.Set();
        }
        if (thread is not null && thread != Thread.CurrentThread && !thread.Join(2000))
        {
            Report(new TimeoutException("D3D11 presentation thread did not stop within 2 seconds."));
            return;
        }
        changed.Dispose();
    }

    unsafe void Render(nint hwnd)
    {
        try
        {
            D3D11CreateDevice(null, DriverType.Hardware, DeviceCreationFlags.BgraSupport,
                [FeatureLevel.Level_11_1, FeatureLevel.Level_11_0], out ID3D11Device device, out ID3D11DeviceContext context).CheckError();
            using (device)
            using (context)
            using (var factory = CreateDXGIFactory2<IDXGIFactory2>(false))
            using (var completion = device.CreateQuery(new QueryDescription(QueryType.Event)))
            {
                using (var dxgiDevice = device.QueryInterface<IDXGIDevice1>()) dxgiDevice.MaximumFrameLatency = 1;
                factory.MakeWindowAssociation(hwnd, WindowAssociationFlags.IgnoreAltEnter).CheckError();
                IDXGISwapChain1? swap = null;
                byte[]? lastPixels = null;
                var width = 0;
                var height = 0;
                try
                {
                    while (true)
                    {
                        DecodedPixels? pixels;
                        lock (gate)
                        {
                            if (stopped) return;
                            pixels = pending;
                            pending = null;
                        }
                        if (pixels is null) { changed.WaitOne(250); continue; }
                        if (pixels.Width == width && pixels.Height == height && lastPixels is not null &&
                            pixels.Bgra.AsSpan().SequenceEqual(lastPixels)) continue;
                        if (pixels.Width != width || pixels.Height != height)
                        {
                            swap?.Dispose();
                            swap = factory.CreateSwapChainForHwnd(device, hwnd, new SwapChainDescription1
                            {
                                Width = (uint)pixels.Width, Height = (uint)pixels.Height,
                                Format = Format.B8G8R8A8_UNorm, BufferCount = 2,
                                BufferUsage = Usage.RenderTargetOutput, SampleDescription = new(1, 0),
                                SwapEffect = SwapEffect.FlipDiscard, Scaling = Scaling.Stretch, AlphaMode = AlphaMode.Ignore
                            });
                            width = pixels.Width;
                            height = pixels.Height;
                            Volatile.Write(ref sourceWidth, width);
                            Volatile.Write(ref sourceHeight, height);
                            Dispatcher.UIThread.Post(InvalidateMeasure);
                        }
                        using (var backBuffer = swap!.GetBuffer<ID3D11Texture2D>(0))
                            fixed (byte* source = pixels.Bgra)
                                context.UpdateSubresource(backBuffer, 0, null, (nint)source, (uint)(width * 4), 0);
                        var presentResult = swap!.Present(0, PresentFlags.None);
                        presentResult.CheckError();
                        if (presentResult.Code != 0) continue;
                        // The event confirms GPU commands after Present; it does not measure physical scan-out.
                        context.End(completion);
                        context.Flush();
                        uint done = 0;
                        var deadline = Stopwatch.GetTimestamp() + Stopwatch.Frequency;
                        while (true)
                        {
                            var result = context.GetData(completion, (nint)(&done), sizeof(uint), AsyncGetDataFlags.DoNotFlush);
                            result.CheckError();
                            if (result.Code == 0 && done != 0) break;
                            lock (gate) { if (stopped) return; }
                            if (Stopwatch.GetTimestamp() >= deadline) throw new TimeoutException("GPU presentation confirmation exceeded 1 second.");
                            Thread.Yield();
                        }
                        var completed = Stopwatch.GetTimestamp();
                        lastPixels = pixels.Bgra;
                        Presented?.Invoke(pixels.Pts, completed);
                    }
                }
                finally { swap?.Dispose(); }
            }
        }
        catch (Exception error) { Report(error); }
    }

    void Report(Exception error)
    {
        Console.Error.WriteLine($"[GPU presentation] {error}");
        try { Failed?.Invoke(error); }
        catch (Exception callbackError) { Console.Error.WriteLine($"[GPU presentation error callback] {callbackError}"); }
    }

    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    static extern nint CreateWindowEx(uint extendedStyle, string className, string name, uint style,
        int x, int y, int width, int height, nint parent, nint menu, nint instance, nint parameter);
    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    static extern bool DestroyWindow(nint hwnd);
}

// Source: FfmpegRegression.cs
static class FfmpegRegression
{
    public static void RunStaticLowBandwidth(AppConfiguration config, string output)
    {
        Directory.CreateDirectory(output);
        var source = new PixelSequence(1280, 720);
        var results = new List<object>(); var passed = true;
        foreach (var name in new[] { "libx264", "libvpx-vp9", "libaom-av1" })
        {
            try
            {
                var entry = FindPreset(config, name);
                var result = CodecTest(entry.Key, entry.Value, source, output, 500, 12);
                results.Add(result); passed &= result.Passed;
            }
            catch (Exception ex) { Console.Error.WriteLine(ex); passed = false; results.Add(new { Encoder = name, Passed = false, Error = ex.ToString() }); }
        }
        File.WriteAllText(Path.Combine(output, "static-500kbps.json"), JsonSerializer.Serialize(new
        {
            Passed = passed, ConfiguredCapKbps = 500, MotionSeconds = 2, StaticSeconds = 12,
            Scope = "Synthetic pixels through real FFmpeg encoder/decoder only, at 30 media FPS; no capture, transport or rendering. Repeated frozen pixels are submitted normally. Tail byte count includes coded frame headers and actual periodic keyframes; no application idle suppression or forced refinement is added.",
            Results = results
        }, AppConfiguration.JsonOptions));
        Environment.ExitCode = passed ? 0 : 1;
    }

    public static void RunControl(AppConfiguration config, string output)
    {
        Directory.CreateDirectory(output);
        var report = IntegrationTest(config).GetAwaiter().GetResult();
        File.WriteAllText(Path.Combine(output, "control-regression.json"), JsonSerializer.Serialize(report, AppConfiguration.JsonOptions));
        Environment.ExitCode = report.Passed ? 0 : 1;
        Console.WriteLine($"Manual control regression {(report.Passed ? "PASS" : "FAIL")}: {Path.GetFullPath(output)}");
    }

    public static void Run(AppConfiguration config, string output)
    {
        Directory.CreateDirectory(output);
        var started = DateTime.UtcNow;
        var source = new PixelSequence(1280, 720);
        var candidates = new[] { "libx264", "libvpx-vp9", "libaom-av1" };
        var results = new List<object>();
        var pass = true;
        SaveBitmap(Path.Combine(output, "frozen-source.bmp"), source.GetFrame(59), 1280, 720);
        foreach (var encoderName in candidates)
        {
            try
            {
                var entry = FindPreset(config, encoderName);
                var result = CodecTest(entry.Key, entry.Value, source, output);
                results.Add(result); pass &= result.Passed;
                File.WriteAllText(Path.Combine(output, encoderName + ".json"), JsonSerializer.Serialize(result, AppConfiguration.JsonOptions));
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine(ex); pass = false;
                results.Add(new { Encoder = encoderName, Passed = false, Error = ex.ToString() });
            }
        }
        object integration;
        try
        {
            var result = IntegrationTest(config).GetAwaiter().GetResult();
            integration = result; pass &= result.Passed;
        }
        catch (Exception ex) { Console.Error.WriteLine(ex); pass = false; integration = new { Passed = false, Error = ex.ToString() }; }
        var report = new
        {
            Passed = pass, StartedUtc = started, CompletedUtc = DateTime.UtcNow, Ffmpeg = FfmpegRuntime.Version,
            CodecIsolationScope = "Synthetic generic pixels only; 1280x720 at 30 media FPS, 1 Mbps codec cap, 2 seconds motion then 4 seconds frozen last motion frame. Repeated frames are submitted without custom motion detection or enhancement. Runs as fast as the codec permits; no capture, UDP or display, and no end-to-end latency claim.",
            QualityInterpretation = "Luma PSNR compares reconstructed full-range BT.709 luma to the frozen source. Quality improvement is reported, not guaranteed and not used to turn codec functionality into a pass. Native encoder frame skipping is allowed: samples use the nearest decoded static frame and report its actual PTS. A final skipped frame retains the last decoded surface. Decoded frame count must equal encoded packet count for these one-frame-per-packet presets. Periodic keyframes follow each JSON preset. Identical pixels report 100 dB.",
            RateAcceptance = "Encoded total must fit 1 Mbps over media duration plus at most 100 kbit (12500 bytes) of initial VBV burst. This is a codec bitstream check; transport separately enforces actual wire pacing including headers.",
            CodecResults = results, Integration = integration
        };
        File.WriteAllText(Path.Combine(output, "ffmpeg-regression.json"), JsonSerializer.Serialize(report, AppConfiguration.JsonOptions));
        Environment.ExitCode = pass ? 0 : 1;
        Console.WriteLine($"FFmpeg regression {(pass ? "PASS" : "FAIL")}: {Path.GetFullPath(output)}");
    }

    static KeyValuePair<string, CodecPreset> FindPreset(AppConfiguration config, string encoderName)
    {
        foreach (var entry in config.Presets)
            if (entry.Value.Enabled && new FfmpegArguments(entry.Value.EncoderArguments).CodecName == encoderName) return entry;
        throw new InvalidOperationException($"No enabled JSON preset for required regression encoder {encoderName}.");
    }

    sealed record QualityPoint(double StaticSeconds, long Pts, double PsnrDb, bool KeyFrame);
    sealed record CodecResult(string Preset, string Encoder, string Decoder, bool Passed, int InputFrames, int DecodedFrames,
        int PacketCount, long EncodedBytes, double StreamMbps, double MotionMbps, double StaticMbps,
        int ConfiguredCapKbps, bool CodecRateWithinCapBudget, long RateBudgetBytes, long TailOneSecondBytes,
        double TailOneSecondMbps, long[] StaticKeyframePts, double MeanEncodeMs, double P95EncodeMs,
        double MeanDecodeMs, double P95DecodeMs, double WallSeconds, List<QualityPoint> StaticQuality,
        double? StaticGainDb, string StaticObservation, int StaticKeyframes, string TimingBoundary,
        string EncoderArguments, string DecoderArguments);

    static CodecResult CodecTest(string presetId, CodecPreset preset, PixelSequence source, string output, int bitrateKbps = 1000, int staticSeconds = 4)
    {
        const int fps = 30, firstStatic = fps * 2;
        var lastIndex = firstStatic + fps * staticSeconds;
        var sourcePixels = source.GetFrame(firstStatic - 1);
        var referenceLuma = Luma(sourcePixels);
        using var encoder = new FfmpegEncoder(preset.EncoderArguments, 1280, 720, fps, bitrateKbps);
        using var decoder = new FfmpegDecoder(preset.DecoderArguments);
        var encodeMs = new List<double>(); var decodeMs = new List<double>();
        var qualities = new List<QualityPoint>();
        var sampleTargets = new[] { 0, 1, 2, 4, 8, staticSeconds }.Where(second => second <= staticSeconds).Distinct().Order().Select(second => firstStatic + fps * second).ToArray();
        var requested = new Queue<int>(sampleTargets);
        var keyframes = new HashSet<long>();
        var decodedFrames = 0; var packets = 0; var staticKeyframes = 0; long bytes = 0, motionBytes = 0, staticBytes = 0, tailBytes = 0;
        byte[]? firstPixels = null, lastPixels = null;
        DecodedPixels? previousStaticFrame = null;
        var watch = Stopwatch.StartNew();

        void Observe(DecodedPixels frame)
        {
            if (frame.Width != 1280 || frame.Height != 720) throw new InvalidDataException("Codec changed regression dimensions.");
            decodedFrames++;
            if (frame.Pts < firstStatic) return;
            firstPixels ??= frame.Bgra; lastPixels = frame.Bgra;
            while (requested.TryPeek(out var target) && frame.Pts >= target)
            {
                requested.Dequeue();
                var sample = previousStaticFrame != null && target - previousStaticFrame.Pts < frame.Pts - target ? previousStaticFrame : frame;
                qualities.Add(new((target - firstStatic) / (double)fps, sample.Pts, Psnr(referenceLuma, sample.Bgra), keyframes.Contains(sample.Pts)));
            }
            previousStaticFrame = frame;
        }
        void DecodePackets(IReadOnlyList<CodecPacket> encoded)
        {
            foreach (var packet in encoded)
            {
                packets++; bytes += packet.Data.Length;
                if (packet.Pts < firstStatic) motionBytes += packet.Data.Length; else staticBytes += packet.Data.Length;
                if (packet.Pts > lastIndex - fps && packet.Pts <= lastIndex) tailBytes += packet.Data.Length;
                if (packet.KeyFrame) { keyframes.Add(packet.Pts); if (packet.Pts >= firstStatic) staticKeyframes++; }
                var start = Stopwatch.GetTimestamp();
                var frames = decoder.Decode(packet.Data, packet.Pts);
                decodeMs.Add(ElapsedMs(start));
                foreach (var frame in frames) Observe(frame);
            }
        }
        for (var index = 0; index <= lastIndex; index++)
        {
            var pixels = index < firstStatic ? source.GetFrame(index) : sourcePixels;
            var start = Stopwatch.GetTimestamp();
            var encoded = encoder.Encode(pixels, index, index == 0);
            encodeMs.Add(ElapsedMs(start)); DecodePackets(encoded);
        }
        DecodePackets(encoder.Flush());
        foreach (var frame in decoder.Flush()) Observe(frame);
        while (requested.TryDequeue(out var target) && previousStaticFrame != null)
            qualities.Add(new((target - firstStatic) / (double)fps, previousStaticFrame.Pts,
                Psnr(referenceLuma, previousStaticFrame.Bgra), keyframes.Contains(previousStaticFrame.Pts)));
        watch.Stop();
        if (firstPixels != null) SaveBitmap(Path.Combine(output, encoder.Name + "-static-first.bmp"), firstPixels, 1280, 720);
        if (lastPixels != null) SaveBitmap(Path.Combine(output, encoder.Name + "-static-final.bmp"), lastPixels, 1280, 720);
        var gain = qualities.Count >= 2 ? (double?)(qualities[^1].PsnrDb - qualities[0].PsnrDb) : null;
        var rateBudget = (long)Math.Ceiling((lastIndex + 1.0) / fps * bitrateKbps * 1000 / 8) + 12500;
        var result = new CodecResult(presetId, encoder.Name, decoder.Name,
            decodedFrames > 0 && decodedFrames == packets && qualities.Count == sampleTargets.Length && bytes <= rateBudget, lastIndex + 1, decodedFrames, packets, bytes,
            bytes * 8.0 / ((lastIndex + 1.0) / fps) / 1_000_000, motionBytes * 8.0 / 2 / 1_000_000,
            staticBytes * 8.0 / ((lastIndex + 1.0 - firstStatic) / fps) / 1_000_000,
            bitrateKbps, bytes <= rateBudget, rateBudget, tailBytes, tailBytes * 8.0 / 1_000_000,
            keyframes.Where(pts => pts >= firstStatic).Order().ToArray(), Mean(encodeMs), Percentile(encodeMs, .95),
            Mean(decodeMs), Percentile(decodeMs, .95), watch.Elapsed.TotalSeconds, qualities, gain,
            gain == null ? "Insufficient static decoded samples" : gain > .1 ? "Static quality improved by more than 0.1 dB" : gain < -.1 ? "Static quality decreased by more than 0.1 dB" : "Static quality remained within 0.1 dB",
            staticKeyframes, "Encode includes BGRA conversion, codec call and packet copy; decode includes packet copy, codec call and BGRA conversion. Initialization, source generation, PSNR and flush are excluded from per-call timing.",
            preset.EncoderArguments, preset.DecoderArguments);
        Console.WriteLine($"{encoder.Name}: decoded {decodedFrames}, encode {result.MeanEncodeMs:F2} ms, static PSNR gain {gain:F2} dB");
        return result;
    }

    sealed record IntegrationStep(string Name, bool Passed, string Preset, int LimitKbps, int Generation, long ReceivedFrames, string Message);
    sealed record IntegrationResult(bool Passed, List<IntegrationStep> Steps, object Session, string Scope);

    static async Task<IntegrationResult> IntegrationTest(AppConfiguration config)
    {
        var h264 = FindPreset(config, "libx264").Key;
        var vp9 = FindPreset(config, "libvpx-vp9").Key;
        var av1 = FindPreset(config, "libaom-av1").Key;
        var testConfig = config with { InitialPreset = h264, InitialBitrateKbps = 1000 };
        var source = new PixelSequence(config.Width, config.Height);
        var sourceIndex = 0; long frameCount = 0;
        var statuses = new List<SessionStatus>(); var statusGate = new object();
        using var session = new DemoSession(testConfig, () => source.GetFrame(Interlocked.Increment(ref sourceIndex) % 120));
        session.FrameReceived += _ => Interlocked.Increment(ref frameCount);
        session.StatusChanged += status => { lock (statusGate) statuses.Add(status); };
        var steps = new List<IntegrationStep>();
        try
        {
            await session.StartAsync().WaitAsync(TimeSpan.FromSeconds(20));
            await AwaitFrames(session.AppliedGeneration, 0);
            await AwaitStatus(h264, 1000);
            steps.Add(new("Initial H.264", true, h264, 1000, session.AppliedGeneration, Interlocked.Read(ref frameCount), "Initial decoded UDP frame received"));
            await Apply("Switch to VP9", vp9, 1000);
            await Apply("Switch to AV1", av1, 1000);
            await Apply("Return to H.264", h264, 1000);
            foreach (var cap in new[] { 500, 1000, 2000 }) await Apply("Manual bitrate " + cap, h264, cap);
            var beforeGeneration = session.AppliedGeneration;
            var beforeFrames = Interlocked.Read(ref frameCount);
            var av2 = config.Presets.FirstOrDefault(entry => entry.Key.Contains("av2", StringComparison.OrdinalIgnoreCase));
            if (av2.Key == null) throw new InvalidOperationException("AV2 preset missing; unsupported backend rejection cannot be verified.");
            var rejected = await session.ApplyAsync(av2.Key, 1000).WaitAsync(TimeSpan.FromSeconds(10));
            await AwaitFrames(beforeGeneration, beforeFrames);
            steps.Add(new("Unavailable AV2 preserves running stream", !rejected.Success && session.AppliedGeneration == beforeGeneration,
                av2.Key, 1000, session.AppliedGeneration, Interlocked.Read(ref frameCount), rejected.Message));
            var diagnosticsBefore = DiagnosticFrames();
            var enabledDiagnostics = await session.SetPacketDiagnosticsAsync(true).WaitAsync(TimeSpan.FromSeconds(5));
            if (!enabledDiagnostics.Success) throw new InvalidOperationException(enabledDiagnostics.Message);
            var diagnosticWait = Stopwatch.StartNew();
            while (DiagnosticFrames() <= diagnosticsBefore)
            {
                if (diagnosticWait.Elapsed > TimeSpan.FromSeconds(3)) throw new TimeoutException("Enabled diagnostic UDP stream did not deliver any frame.");
                await Task.Delay(30);
            }
            await AwaitStatus(h264, 2000);
            steps.Add(new("Enable separate diagnostic UDP", session.AppliedGeneration == beforeGeneration,
                h264, 2000, session.AppliedGeneration, Interlocked.Read(ref frameCount), $"Received diagnostic frames: {DiagnosticFrames()}"));
            var beforeDisableFrames = Interlocked.Read(ref frameCount);
            var disabledDiagnostics = await session.SetPacketDiagnosticsAsync(false).WaitAsync(TimeSpan.FromSeconds(5));
            if (!disabledDiagnostics.Success) throw new InvalidOperationException(disabledDiagnostics.Message);
            await AwaitFrames(beforeGeneration, beforeDisableFrames); await Task.Delay(100);
            var afterDisable = DiagnosticFrames();
            await AwaitFrames(beforeGeneration, Interlocked.Read(ref frameCount)); await Task.Delay(250);
            await AwaitStatus(h264, 2000);
            steps.Add(new("Disable diagnostics preserves video", DiagnosticFrames() == afterDisable && session.AppliedGeneration == beforeGeneration,
                h264, 2000, session.AppliedGeneration, Interlocked.Read(ref frameCount), $"Diagnostic count remained {afterDisable} while video decoded further frames"));
            int statusStart;
            lock (statusGate) statusStart = statuses.Count;
            await Task.Delay(1600);
            SessionStatus[] stable;
            lock (statusGate) stable = statuses.Skip(statusStart).ToArray();
            var unchanged = session.AppliedGeneration == beforeGeneration && stable.Length >= 3 && stable.All(status => status.ActivePreset == h264 && status.AppliedLimitKbps == 2000);
            steps.Add(new("Estimation does not modify manual selection", unchanged, h264, 2000, session.AppliedGeneration,
                Interlocked.Read(ref frameCount), $"Observed {stable.Length} status reports without another control request"));
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine(ex);
            steps.Add(new("Integration failure", false, "", 0, session.AppliedGeneration, Interlocked.Read(ref frameCount), ex.ToString()));
        }
        finally { await session.StopAsync(); }
        return new(steps.Count >= 11 && steps.All(step => step.Passed), steps, session.GetReport(),
            "Synthetic source through real FFmpeg, localhost UDP video and TCP manual control; decoded frame receipt confirms each new generation. No screen capture or UI render is claimed by this test.");

        long DiagnosticFrames() => JsonSerializer.SerializeToElement(session.GetReport()).GetProperty("ReceivedDiagnosticFrames").GetInt64();

        async Task Apply(string name, string presetId, int cap)
        {
            var before = Interlocked.Read(ref frameCount);
            var result = await session.ApplyAsync(presetId, cap).WaitAsync(TimeSpan.FromSeconds(15));
            if (!result.Success) throw new InvalidOperationException(name + ": " + result.Message);
            await AwaitFrames(result.Generation, before);
            await AwaitStatus(presetId, cap);
            steps.Add(new(name, session.AppliedGeneration == result.Generation, presetId, cap, result.Generation,
                Interlocked.Read(ref frameCount), "Sender status confirmed exact preset/cap and receiver continued decoding; same-session bitrate changes may preserve generation"));
        }
        async Task AwaitFrames(int generation, long before)
        {
            var watch = Stopwatch.StartNew();
            while (session.DecodedGeneration != generation || Interlocked.Read(ref frameCount) <= before)
            {
                if (watch.Elapsed > TimeSpan.FromSeconds(15)) throw new TimeoutException($"Generation {generation} has no decoded frame; current decoded generation {session.DecodedGeneration}.");
                await Task.Delay(30);
            }
        }
        async Task AwaitStatus(string presetId, int cap)
        {
            var watch = Stopwatch.StartNew();
            while (true)
            {
                lock (statusGate)
                    if (statuses.Count > 0 && statuses[^1].ActivePreset == presetId && statuses[^1].AppliedLimitKbps == cap) return;
                if (watch.Elapsed > TimeSpan.FromSeconds(3)) throw new TimeoutException($"Status did not confirm {presetId} at {cap} kbps.");
                await Task.Delay(30);
            }
        }
    }

    static double ElapsedMs(long start) => (Stopwatch.GetTimestamp() - start) * 1000.0 / Stopwatch.Frequency;
    static double Mean(List<double> values) => values.Count == 0 ? 0 : values.Average();
    static double Percentile(List<double> values, double fraction) => values.Count == 0 ? 0 : values.Order().ElementAt(Math.Clamp((int)Math.Ceiling(values.Count * fraction) - 1, 0, values.Count - 1));
    static byte[] Luma(byte[] pixels)
    {
        var result = new byte[pixels.Length / 4];
        for (int i = 0, p = 0; i < result.Length; i++, p += 4) result[i] = (byte)((19 * pixels[p] + 183 * pixels[p + 1] + 54 * pixels[p + 2] + 128) >> 8);
        return result;
    }
    static double Psnr(byte[] reference, byte[] actual)
    {
        if (actual.Length != reference.Length * 4) throw new InvalidDataException("PSNR frame dimensions mismatch.");
        long error = 0;
        for (int i = 0, p = 0; i < reference.Length; i++, p += 4)
        {
            int luma = (19 * actual[p] + 183 * actual[p + 1] + 54 * actual[p + 2] + 128) >> 8;
            int delta = reference[i] - luma; error += delta * delta;
        }
        return error == 0 ? 100 : 10 * Math.Log10(255.0 * 255 * reference.Length / error);
    }

    static void SaveBitmap(string path, byte[] bgra, int width, int height)
    {
        using var writer = new BinaryWriter(File.Create(path));
        writer.Write((ushort)0x4D42); writer.Write(54 + bgra.Length); writer.Write(0); writer.Write(54);
        writer.Write(40); writer.Write(width); writer.Write(-height); writer.Write((ushort)1); writer.Write((ushort)32);
        writer.Write(0); writer.Write(bgra.Length); writer.Write(3780); writer.Write(3780); writer.Write(0); writer.Write(0); writer.Write(bgra);
    }

    sealed class PixelSequence
    {
        readonly int width, height;
        readonly byte[] background;
        static readonly string[] Glyphs = ["01110100011000110001100011000101110", "00100011000010000100001000010001110", "01110100010000100010001000100011111", "11110000010000101110000010000111110", "00010001100101010010111110001000010", "11111100001000011110000010000111110", "01110100001000011110100011000101110", "11111000010001000100010000100001000", "01110100011000101110100011000101110", "01110100011000101111000010000101110"];

        public PixelSequence(int width, int height)
        {
            this.width = width; this.height = height; background = new byte[checked(width * height * 4)];
            for (var y = 0; y < height; y++) for (var x = 0; x < width; x++)
            {
                var shade = (byte)(45 + x * 160 / width + ((x / 16 + y / 16) % 2) * 24);
                Set(background, x, y, shade, (byte)Math.Min(255, shade + y * 20 / height), shade);
            }
            for (var y = 15; y + 14 < height; y += 37)
                for (var x = 15; x + 10 < width; x += 21) DrawGlyph(background, x, y, (x / 21 + y / 37) % 10, 2);
        }

        public byte[] GetFrame(int index)
        {
            var result = (byte[])background.Clone();
            int left = width / 10, top = height / 5, patchWidth = width * 4 / 5, patchHeight = height * 3 / 5;
            for (var y = 0; y < patchHeight; y++) for (var x = 0; x < patchWidth; x++)
            {
                int u = x + index * 7, v = y + index * 3;
                int checker = ((u / 7 + v / 7) & 1) * 75;
                byte shade = (byte)(50 + checker + ((u + v) % 120));
                Set(result, left + x, top + y, shade, (byte)(40 + (u * 3 + v) % 170), (byte)(60 + checker));
            }
            for (var y = top + 8; y + 14 < top + patchHeight; y += 29)
                for (var x = left + 8; x + 10 < left + patchWidth; x += 31) DrawGlyph(result, x, y, (x / 31 + y / 29 + index / 4) % 10, 2);
            return result;
        }

        void DrawGlyph(byte[] pixels, int x, int y, int digit, int scale)
        {
            var glyph = Glyphs[digit];
            for (var row = 0; row < 7; row++) for (var col = 0; col < 5; col++)
                if (glyph[row * 5 + col] == '1')
                    for (var dy = 0; dy < scale; dy++) for (var dx = 0; dx < scale; dx++) Set(pixels, x + col * scale + dx, y + row * scale + dy, 15, 15, 15);
        }
        void Set(byte[] pixels, int x, int y, byte red, byte green, byte blue)
        {
            int p = (y * width + x) * 4; pixels[p] = blue; pixels[p + 1] = green; pixels[p + 2] = red; pixels[p + 3] = 255;
        }
    }
}

// Source: FfmpegRemote.cs
public sealed record RemoteOptions(string Host, int Port, string Token);
sealed record RemoteRequest(string Kind, string Token = "", int VideoPort = 0, int DiagnosticPort = 0,
    string Session = "", ControlCommand? Command = null);
sealed record RemoteWelcome(string Session, int SenderPort, int Width, int Height, int SourceWidth, int SourceHeight,
    int FramesPerSecond, string InitialPreset, int InitialBitrateKbps, Dictionary<string, CodecPreset> Presets);
sealed record RemoteReply(bool Success, string Message = "", RemoteWelcome? Welcome = null, ControlResult? Control = null,
    NetworkSnapshot? Network = null, string Preset = "", int LimitKbps = 0, bool Diagnostics = false,
    long ReceiveTick = 0, long SendTick = 0, long Frequency = 0);

static class RemoteWire
{
    public static async Task WriteAsync<T>(NetworkStream stream, T value, CancellationToken token)
    {
        var bytes = JsonSerializer.SerializeToUtf8Bytes(value);
        if (bytes.Length > 65536) throw new InvalidDataException("Remote control message exceeds 64 KiB.");
        var header = new byte[4]; BinaryPrimitives.WriteInt32LittleEndian(header, bytes.Length);
        await stream.WriteAsync(header, token); await stream.WriteAsync(bytes, token);
    }

    public static async Task<T> ReadAsync<T>(NetworkStream stream, CancellationToken token)
    {
        var header = new byte[4]; await stream.ReadExactlyAsync(header, token);
        var size = BinaryPrimitives.ReadInt32LittleEndian(header);
        if (size is < 1 or > 65536) throw new InvalidDataException("Invalid remote control message length.");
        var bytes = new byte[size]; await stream.ReadExactlyAsync(bytes, token);
        return JsonSerializer.Deserialize<T>(bytes) ?? throw new InvalidDataException("Empty remote message.");
    }
}

sealed class RemoteConnection : IDisposable
{
    readonly TcpClient client;
    readonly SemaphoreSlim gate = new(1, 1);
    public ClockEstimate Clock { get; } = new();
    public IPEndPoint Endpoint => (IPEndPoint)client.Client.RemoteEndPoint!;
    RemoteConnection(TcpClient client) => this.client = client;

    public static async Task<RemoteConnection> ConnectAsync(RemoteOptions options, CancellationToken token)
    {
        var client = new TcpClient(AddressFamily.InterNetwork) { NoDelay = true };
        try { await client.ConnectAsync(options.Host, options.Port, token); return new(client); }
        catch { client.Dispose(); throw; }
    }

    public async Task<RemoteReply> ExchangeAsync(RemoteRequest request, CancellationToken token)
    {
        await gate.WaitAsync(token);
        try
        {
            using var timeout = CancellationTokenSource.CreateLinkedTokenSource(token);
            timeout.CancelAfter(TimeSpan.FromSeconds(15));
            var started = Stopwatch.GetTimestamp();
            await RemoteWire.WriteAsync(client.GetStream(), request, timeout.Token);
            var reply = await RemoteWire.ReadAsync<RemoteReply>(client.GetStream(), timeout.Token);
            Clock.Observe(started, Stopwatch.GetTimestamp(), reply.ReceiveTick, reply.SendTick, reply.Frequency);
            if (!reply.Success) throw new IOException(reply.Message);
            return reply;
        }
        catch { client.Dispose(); throw; }
        finally { gate.Release(); }
    }
    public void Dispose() => client.Dispose();
}

public sealed class ClockEstimate
{
    readonly object gate = new();
    readonly Queue<(long Local, double Offset, double Error)> samples = new();
    double offsetSeconds, uncertaintyMs = double.PositiveInfinity;
    public double UncertaintyMs { get { lock (gate) return uncertaintyMs; } }
    public void Observe(long t1, long t4, long t2, long t3, long frequency)
    {
        if (frequency <= 0 || t3 < t2 || t4 < t1) return;
        var localDuration = (t4 - t1) / (double)Stopwatch.Frequency;
        var remoteDuration = (t3 - t2) / (double)frequency;
        var uncertainty = (localDuration - remoteDuration) * 500;
        if (uncertainty < 0 || uncertainty > 2000) return;
        var offset = (t1 / (double)Stopwatch.Frequency - t2 / (double)frequency +
            t4 / (double)Stopwatch.Frequency - t3 / (double)frequency) / 2;
        lock (gate)
        {
            samples.Enqueue((t4, offset, uncertainty));
            while (samples.TryPeek(out var sample) && (t4 - sample.Local > Stopwatch.Frequency * 10 || samples.Count > 64)) samples.Dequeue();
            var best = samples.MinBy(sample => sample.Error);
            offsetSeconds = best.Offset; uncertaintyMs = best.Error;
        }
    }
    public long ToLocal(long tick, long frequency)
    {
        lock (gate) return checked((long)((tick / (double)frequency + offsetSeconds) * Stopwatch.Frequency));
    }
}

public sealed partial class DemoSession
{
    readonly RemoteOptions? remoteOptions;
    RemoteConnection? remote;
    RemoteWelcome? welcome;
    IPEndPoint? diagnosticDestination;
    NetworkSnapshot? remoteNetwork;
    readonly object remoteTimingGate = new();
    readonly Dictionary<long, FrameDiagnostic> remoteDiagnostics = new();
    readonly Dictionary<long, long> remotePresented = new();
    readonly Queue<long> remotePresentationTicks = new();
    public bool IsRemote => remoteOptions != null;
    public AppConfiguration Configuration => config;
    internal int SenderPort => sender?.ActualPort ?? throw new InvalidOperationException("Sender not started.");
    public int RemoteSourceWidth => welcome?.SourceWidth ?? config.Width;
    public int RemoteSourceHeight => welcome?.SourceHeight ?? config.Height;
    string RemoteTimingDescription => packetDiagnosticsEnabled
        ? $"跨机估算，时钟采样不确定度 ±{remote!.Clock.UncertaintyMs:F2} ms（不含漂移）"
        : "诊断关闭：跨机捕获到呈现耗时不可测；画面继续接收";

    public DemoSession(AppConfiguration config, RemoteOptions options)
    {
        this.config = config; remoteOptions = options;
        capture = () => throw new InvalidOperationException("Controller must not capture or encode its desktop.");
    }

    async Task StartRemoteAsync()
    {
        receiver = new(); receiver.VideoReceived += ReceiveVideo;
        diagnosticsReceiver = new(remote: true); diagnosticsReceiver.Received += ReceiveDiagnostic;
        remote = await RemoteConnection.ConnectAsync(remoteOptions!, stop.Token);
        var reply = await remote.ExchangeAsync(new("hello", remoteOptions!.Token, receiver.Port, diagnosticsReceiver.Port), stop.Token);
        welcome = reply.Welcome ?? throw new InvalidDataException("Host did not return stream configuration.");
        config = config with { Width = welcome.Width, Height = welcome.Height, FramesPerSecond = welcome.FramesPerSecond,
            InitialPreset = welcome.InitialPreset, InitialBitrateKbps = welcome.InitialBitrateKbps, Presets = welcome.Presets };
        receiver.SetExpectedSource(new(remote.Endpoint.Address, welcome.SenderPort));
        diagnosticsReceiver.SetExpectedSource(new(remote.Endpoint.Address, welcome.SenderPort));
        for (var i = 0; i < 4; i++) await remote.ExchangeAsync(new("status"), stop.Token);
        await SetPacketDiagnosticsAsync(true);
        var applied = await ApplyAsync(config.InitialPreset, config.InitialBitrateKbps);
        if (!applied.Success) throw new IOException(applied.Message);
        statusTask = Task.Run(StatusLoopAsync);
    }

    async Task<ControlResult> RemoteControlAsync(ControlCommand command)
    {
        var reply = await remote!.ExchangeAsync(new("control", Command: command), stop.Token);
        var result = reply.Control ?? throw new InvalidDataException("Missing control acknowledgement.");
        if (result.Success)
        {
            Volatile.Write(ref appliedGeneration, result.Generation);
            if (command.Kind == "apply") { activePreset = command.PresetId; appliedLimit = command.LimitKbps; }
            if (command.Kind == "diagnostics") Volatile.Write(ref packetDiagnosticsEnabled, command.DiagnosticsEnabled);
        }
        return result;
    }

    async Task<NetworkSnapshot> ReadRemoteStatusAsync()
    {
        var reply = await remote!.ExchangeAsync(new("status"), stop.Token);
        activePreset = reply.Preset; appliedLimit = reply.LimitKbps; packetDiagnosticsEnabled = reply.Diagnostics;
        message = "远端发送；预设和码率完全手动";
        return remoteNetwork = reply.Network ?? throw new InvalidDataException("Missing sender network statistics.");
    }

    public async Task<RemoteInputClient> ConnectRemoteInputAsync(CancellationToken token)
    {
        if (remoteOptions == null || welcome == null) throw new InvalidOperationException("Remote session not connected.");
        var client = new TcpClient(AddressFamily.InterNetwork) { NoDelay = true };
        try
        {
            await client.ConnectAsync(remoteOptions.Host, remoteOptions.Port, token);
            await RemoteWire.WriteAsync(client.GetStream(), new RemoteRequest("input", remoteOptions.Token, Session: welcome.Session), token);
            var reply = await RemoteWire.ReadAsync<RemoteReply>(client.GetStream(), token);
            if (!reply.Success) throw new IOException(reply.Message);
            return new(client);
        }
        catch { client.Dispose(); throw; }
    }

    internal void StartSender(IPEndPoint video, IPEndPoint diagnostics)
    {
        diagnosticDestination = diagnostics;
        sender = new(video, config.Simulation); sender.SetEncoderBitrateKbps(config.InitialBitrateKbps);
        sender.FrameSending += (generation, id, timing) =>
        {
            if (frameClocks.TryGetValue(id, out var clock) && clock.Generation == generation) Volatile.Write(ref clock.Sending, timing);
        };
        encodeTask = Task.Run(EncodeLoop);
    }

    internal async Task<ControlResult> SubmitControlAsync(ControlCommand command, CancellationToken token)
    {
        if (command.Kind is not ("apply" or "keyframe" or "diagnostics")) return new(false, "Unknown control command.", AppliedGeneration);
        var pending = new PendingControl(command, new(TaskCreationOptions.RunContinuationsAsynchronously));
        await commands.Writer.WriteAsync(pending, token);
        return await pending.Completion.Task.WaitAsync(token);
    }

    internal RemoteReply SenderStatus() => new(true, Message: message, Network: sender?.Snapshot, Preset: activePreset,
        LimitKbps: appliedLimit, Diagnostics: packetDiagnosticsEnabled);

    void ApplyRemoteDiagnostic(FrameTimeline clock, FrameDiagnostic diagnostic)
    {
        clock.CaptureTick = remote!.Clock.ToLocal(diagnostic.CaptureStarted, diagnostic.Frequency);
        clock.CapturedTick = remote.Clock.ToLocal(diagnostic.CaptureCompleted, diagnostic.Frequency);
        clock.EncodedTick = remote.Clock.ToLocal(diagnostic.EncodeCompleted, diagnostic.Frequency);
        if (diagnostic.Sending is { } sending)
            clock.Sending = sending with { FirstSendTick = remote.Clock.ToLocal(sending.FirstSendTick, diagnostic.Frequency),
                LastSendTick = remote.Clock.ToLocal(sending.LastSendTick, diagnostic.Frequency) };
        clock.HasRemoteDiagnostic = true;
    }

    void PrepareRemoteFrame(ReceivedVideo video, long tick)
    {
        lock (remoteTimingGate)
        {
            var clock = new FrameTimeline(0, 0, 0, video.Generation) { ReceivedTick = tick, ReassembledTick = video.ReassembledTick };
            if (remoteDiagnostics.Remove(video.FrameId, out var diagnostic) && diagnostic.Generation == video.Generation)
                ApplyRemoteDiagnostic(clock, diagnostic);
            frameClocks[video.FrameId] = clock;
            frameClocks.TryRemove(video.FrameId - 4096, out _);
        }
    }

    void ReceiveRemoteDiagnostic(FrameDiagnostic diagnostic)
    {
        long completed = 0;
        lock (remoteTimingGate)
        {
            if (frameClocks.TryGetValue(diagnostic.FrameId, out var clock) && clock.Generation == diagnostic.Generation)
                ApplyRemoteDiagnostic(clock, diagnostic);
            else remoteDiagnostics[diagnostic.FrameId] = diagnostic;
            remoteDiagnostics.Remove(diagnostic.FrameId - 4096);
            remotePresented.TryGetValue(diagnostic.FrameId, out completed);
        }
        if (completed > 0) ReportPresented(diagnostic.FrameId, completed);
    }

    bool PrepareRemotePresentation(long id, long tick)
    {
        lock (remoteTimingGate)
        {
            if (remotePresented.TryAdd(id, tick)) remotePresentationTicks.Enqueue(tick);
            remotePresented.Remove(id - 4096);
            if (!frameClocks.TryGetValue(id, out var clock) || !clock.HasRemoteDiagnostic) return false;
            remotePresented.Remove(id);
            return true;
        }
    }

    int RemotePresentedFps()
    {
        lock (remoteTimingGate)
        {
            while (remotePresentationTicks.TryPeek(out var tick) && Stopwatch.GetTimestamp() - tick > Stopwatch.Frequency) remotePresentationTicks.Dequeue();
            return remotePresentationTicks.Count;
        }
    }
}

sealed class RemoteHost : IAsyncDisposable
{
    readonly AppConfiguration config;
    readonly string token;
    readonly TcpListener listener;
    readonly CancellationTokenSource stop = new();
    readonly ConcurrentDictionary<int, Task> peers = new();
    readonly object gate = new();
    CancellationTokenSource? activeStop;
    string sessionId = "";
    IPAddress? controller;
    bool hasInput;
    int peerId;
    Task? acceptTask;
    public event Action<string>? Status;
    public RemoteHost(AppConfiguration config, IPAddress address, int port, string token)
    { this.config = config; this.token = token; listener = new(address, port); }

    public void Start()
    {
        listener.Start(8); acceptTask = Task.Run(AcceptAsync);
        Console.Error.WriteLine($"Remote listener ready: {listener.LocalEndpoint}");
        Status?.Invoke($"被控端正在监听 {listener.LocalEndpoint}\n等待主控连接；关闭此窗口停止监听。");
    }

    async Task AcceptAsync()
    {
        try
        {
            while (!stop.IsCancellationRequested)
            {
                var client = await listener.AcceptTcpClientAsync(stop.Token); client.NoDelay = true;
                var id = Interlocked.Increment(ref peerId);
                var task = HandleAsync(client); peers[id] = task;
                _ = task.ContinueWith(_ => peers.TryRemove(id, out var removed), TaskScheduler.Default);
            }
        }
        catch (OperationCanceledException) when (stop.IsCancellationRequested) { Console.Error.WriteLine("Remote listener stopped."); }
        catch (Exception error) { Console.Error.WriteLine(error); Status?.Invoke(error.Message); }
    }

    async Task HandleAsync(TcpClient client)
    {
        using (client)
        using (var timeout = CancellationTokenSource.CreateLinkedTokenSource(stop.Token))
        {
            timeout.CancelAfter(TimeSpan.FromSeconds(10));
            try
            {
                var stream = client.GetStream();
                var hello = await RemoteWire.ReadAsync<RemoteRequest>(stream, timeout.Token);
                var received = Stopwatch.GetTimestamp();
                if (!CryptographicOperations.FixedTimeEquals(SHA256.HashData(Encoding.UTF8.GetBytes(hello.Token)), SHA256.HashData(Encoding.UTF8.GetBytes(token))))
                { await RemoteWire.WriteAsync(stream, new RemoteReply(false, "连接口令错误。"), timeout.Token); return; }
                var address = ((IPEndPoint)client.Client.RemoteEndPoint!).Address;
                if (hello.Kind == "input")
                {
                    CancellationToken inputToken;
                    lock (gate)
                    {
                        if (activeStop == null || hello.Session != sessionId || !address.Equals(controller) || hasInput)
                            throw new InvalidDataException("Input channel does not belong to the active controller.");
                        hasInput = true; inputToken = activeStop.Token;
                    }
                    try
                    {
                        await RemoteWire.WriteAsync(stream, new RemoteReply(true), timeout.Token);
                        using var injector = new Win32InputInjector();
                        await RemoteInputServer.ServePeerAsync(injector, client, inputToken);
                    }
                    finally { lock (gate) hasInput = false; }
                    return;
                }
                if (hello.Kind != "hello" || hello.VideoPort is < 1 or > 65535 || hello.DiagnosticPort is < 1 or > 65535 || hello.VideoPort == hello.DiagnosticPort)
                    throw new InvalidDataException("Invalid connection handshake.");
                CancellationTokenSource lifetime;
                string id;
                lock (gate)
                {
                    if (activeStop != null) throw new InvalidOperationException("被控端已有主控连接。");
                    activeStop = lifetime = CancellationTokenSource.CreateLinkedTokenSource(stop.Token);
                    controller = address; sessionId = id = Convert.ToHexString(RandomNumberGenerator.GetBytes(16));
                }
                try
                {
                    using var capture = new DesktopCapture(config.Width, config.Height);
                    capture.Capture();
                    using var session = new DemoSession(config, capture.Capture);
                    session.StartSender(new(address, hello.VideoPort), new(address, hello.DiagnosticPort));
                    var welcome = new RemoteWelcome(id, session.SenderPort, config.Width, config.Height,
                        capture.Statistics?.SourceWidth ?? config.Width, capture.Statistics?.SourceHeight ?? config.Height,
                        config.FramesPerSecond, config.InitialPreset, config.InitialBitrateKbps, config.Presets);
                    await SendAsync(new(true, Welcome: welcome), received);
                    Status?.Invoke($"主控已连接：{address}\n真实屏幕 → FFmpeg → UDP；键鼠由主控手动启用。");
                    while (!lifetime.IsCancellationRequested)
                    {
                        using var idle = CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token);
                        idle.CancelAfter(TimeSpan.FromSeconds(20));
                        var request = await RemoteWire.ReadAsync<RemoteRequest>(stream, idle.Token);
                        received = Stopwatch.GetTimestamp();
                        if (request.Kind == "status") await SendAsync(session.SenderStatus(), received);
                        else if (request.Kind == "control" && request.Command != null)
                        {
                            var result = await session.SubmitControlAsync(request.Command, idle.Token);
                            await SendAsync(new(true, Control: result), received);
                        }
                        else throw new InvalidDataException("Unknown remote request.");
                    }
                    async Task SendAsync(RemoteReply reply, long tick) => await RemoteWire.WriteAsync(stream,
                        reply with { ReceiveTick = tick, SendTick = Stopwatch.GetTimestamp(), Frequency = Stopwatch.Frequency }, lifetime.Token);
                }
                finally
                {
                    lifetime.Cancel();
                    lock (gate) { activeStop = null; controller = null; sessionId = ""; }
                    Status?.Invoke("主控已断开；已停止捕获发送并释放输入。等待重新连接。");
                }
            }
            catch (EndOfStreamException) { Console.Error.WriteLine("Remote controller disconnected."); }
            catch (OperationCanceledException) { Console.Error.WriteLine("Remote connection cancelled or timed out."); }
            catch (Exception error)
            {
                Console.Error.WriteLine(error); Status?.Invoke(error.Message);
                try { await RemoteWire.WriteAsync(client.GetStream(), new RemoteReply(false, error.Message), stop.Token); }
                catch (Exception replyError) { Console.Error.WriteLine("Remote error reply failed: " + replyError.Message); }
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        stop.Cancel(); listener.Stop();
        if (acceptTask != null) await acceptTask;
        await Task.WhenAll(peers.Values); stop.Dispose();
    }
}

static class RemoteLaunch
{
    public const string Usage = "被控：FRD.exe --host --port 5000 --token 自定口令 [--listen 0.0.0.0]\n主控：FRD.exe --connect 被控IPv4或主机名 --port 5000 --token 相同口令\n无参数：原 localhost Demo。TCP 控制及独立键鼠连接共用被控监听端口，视频和诊断走协商的 UDP 端口。";
    public static int Run(AppConfiguration config, string[] args)
    {
        if (args[0] == "--help") { Console.WriteLine(Usage); ShowMessage(Usage); return 0; }
        var host = args[0] == "--host";
        if (!host && args.Length < 2) throw new ArgumentException(Usage);
        var values = new Dictionary<string, string>();
        for (var i = host ? 1 : 2; i < args.Length; i += 2)
        {
            if (i + 1 >= args.Length || args[i] is not ("--port" or "--token" or "--listen" or "--test-seconds" or "--report") || !values.TryAdd(args[i], args[i + 1]))
                throw new ArgumentException(Usage);
        }
        if (!values.TryGetValue("--port", out var portText) || !int.TryParse(portText, out var port) || port is < 1 or > 65535 ||
            !values.TryGetValue("--token", out var token) || string.IsNullOrWhiteSpace(token)) throw new ArgumentException(Usage);
        if (!host)
        {
            var seconds = int.Parse(values.GetValueOrDefault("--test-seconds", "0"));
            if (seconds is < 0 or > 3600) throw new ArgumentException("Invalid test duration.");
            FfmpegUi.Run(config, seconds, values.GetValueOrDefault("--report"), new(args[1], port, token)); return 0;
        }
        var address = IPAddress.Parse(values.GetValueOrDefault("--listen", "0.0.0.0"));
        if (address.AddressFamily != AddressFamily.InterNetwork) throw new ArgumentException("目前支持 IPv4。");
        HostApplication.Factory = () => new HostWindow(config, address, port, token);
        AppBuilder.Configure<HostApplication>().UsePlatformDetect().StartWithClassicDesktopLifetime([]); return 0;
    }

    static void ShowMessage(string text)
    {
        HostApplication.Factory = () => new Window { Title = "FRD 命令行", Width = 700, Height = 250,
            Content = new TextBlock { Text = text, TextWrapping = Avalonia.Media.TextWrapping.Wrap, Margin = new Thickness(20) } };
        AppBuilder.Configure<HostApplication>().UsePlatformDetect().StartWithClassicDesktopLifetime([]);
    }

    sealed class HostApplication : Application
    {
        public static Func<Window>? Factory;
        public override void Initialize() => Styles.Add(new FluentTheme());
        public override void OnFrameworkInitializationCompleted()
        {
            if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop) desktop.MainWindow = Factory!();
            base.OnFrameworkInitializationCompleted();
        }
    }

    sealed class HostWindow : Window
    {
        readonly RemoteHost server;
        bool closing, finished;
        public HostWindow(AppConfiguration config, IPAddress address, int port, string token)
        {
            Title = $"FRD 被控端 · TCP {port}"; Width = 600; Height = 200;
            var status = new TextBlock { Text = "正在监听…", TextWrapping = Avalonia.Media.TextWrapping.Wrap, Margin = new Thickness(20) };
            Content = status; server = new(config, address, port, token);
            server.Status += text => Avalonia.Threading.Dispatcher.UIThread.Post(() => status.Text = text);
            Opened += (_, _) => { try { server.Start(); } catch (Exception error) { Console.Error.WriteLine(error); status.Text = error.Message; } };
            Closing += async (_, e) =>
            {
                if (finished) return;
                e.Cancel = true; if (closing) return; closing = true;
                try { await server.DisposeAsync(); }
                catch (Exception error) { Console.Error.WriteLine(error); }
                finally { finished = true; Avalonia.Threading.Dispatcher.UIThread.Post(Close); }
            };
        }
    }
}

// Source: FfmpegTransport.cs
public record ReceivedVideo(int Generation, long FrameId, bool KeyFrame, byte[] Data)
{
    public long ReassembledTick { get; init; }
}
public sealed record VideoSendTiming(int PayloadBytes, int Packets, long FirstSendTick, long LastSendTick,
    double PlannedWaitMs, double WakeupOverrunMs);
public record NetworkSnapshot(double SentMbps, double ReceivedMbps, double EstimatedMbps, double DelayTrendMs,
    double LossRate, long SentPackets, long ReceivedPackets, string EstimateState)
{
    public double DiagnosticMbps { get; init; }
    public long DiagnosticPackets { get; init; }
    public int SendBudgetKbps { get; init; }
    public int BurstBudgetWireBytes { get; init; }
    public double SimulatedCapacityMbps { get; init; }
}
public record NetworkSimulation(double CapacityMbps = 0, double LossRate = 0, int MaxDelayMs = 0);

static class VideoDatagram
{
    static readonly ConcurrentDictionary<(string Operation, SocketError Error), byte> transientErrors = new();
    public const uint Magic = 0x32445246;
    public const int Header = 36, MaxSize = 1172, Payload = MaxSize - Header, FeedbackSize = 72;
    public const int MaxFrameSize = 8 * 1024 * 1024, MaxBufferedBytes = 16 * 1024 * 1024;
    public static long Now => Stopwatch.GetTimestamp();
    public static double Seconds(long ticks) => (double)ticks / Stopwatch.Frequency;
    public static void Log(string message, Exception? error = null) =>
        Console.Error.WriteLine($"[UDP] {message}{(error is null ? "" : $": {error}")}");

    public static bool Recoverable(SocketException error, string operation)
    {
        if (error.SocketErrorCode is not (SocketError.ConnectionReset or SocketError.ConnectionRefused or
            SocketError.HostUnreachable or SocketError.NetworkUnreachable or SocketError.NetworkDown or
            SocketError.TimedOut or SocketError.WouldBlock or SocketError.NoBufferSpaceAvailable)) return false;
        if (transientErrors.TryAdd((operation, error.SocketErrorCode), 0))
            Log($"{operation}: transient socket error; packet skipped, socket retained. Repeated {error.SocketErrorCode} errors are suppressed", error);
        return true;
    }
}

public sealed class UdpVideoSender : IDisposable
{
    readonly Socket socket = new(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
    readonly SafeWaitHandle pacingTimer = CreatePacingTimer();
    readonly IPEndPoint destination;
    readonly CancellationTokenSource shutdown = new();
    readonly Thread feedbackThread, delayedThread;
    readonly object sendGate = new(), statsGate = new(), delayGate = new();
    readonly PriorityQueue<(byte[] Data, IPEndPoint Destination), long> delayed = new();
    readonly AutoResetEvent delayedChanged = new(false);
    readonly SendStamp[] stamps = new SendStamp[65536];
    readonly Queue<(long Time, int Sent, long Received)> rates = new();
    readonly Queue<(long Time, int Bytes)> diagnosticRates = new();
    NetworkSimulation simulation;
    int limitKbps = 1000, disposed;
    uint sequence;
    double nextSendTick, delayTrend, deliveryEstimate;
    bool rateLimited = true;
    long sentPackets, receivedPackets, receivedWireBytes, lastFeedbackTick;
    long diagnosticPackets;
    long lastReceiverTick, lastSenderTick, previousReceiverTotal;
    double lossRate;

    readonly record struct SendStamp(uint Sequence, long Tick);

    [DllImport("kernel32.dll", EntryPoint = "CreateWaitableTimerExW", SetLastError = true)]
    static extern SafeWaitHandle CreateWaitableTimerEx(nint attributes, nint name, uint flags, uint access);
    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    static extern bool SetWaitableTimer(SafeWaitHandle timer, ref long dueTime, int period, nint callback, nint state,
        [MarshalAs(UnmanagedType.Bool)] bool resume);
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern uint WaitForSingleObject(SafeWaitHandle handle, uint milliseconds);

    static SafeWaitHandle CreatePacingTimer()
    {
        var timer = CreateWaitableTimerEx(0, 0, 2, 0x1F0003);
        if (timer.IsInvalid) throw new Win32Exception(Marshal.GetLastWin32Error(), "High-resolution packet pacing timer creation failed.");
        return timer;
    }

    public UdpVideoSender(IPEndPoint destination, NetworkSimulation? simulation = null)
    {
        if (destination.AddressFamily != AddressFamily.InterNetwork)
            throw new ArgumentException("The 1200-byte MTU budget currently requires IPv4.", nameof(destination));
        this.destination = destination;
        this.simulation = ValidateSimulation(simulation ?? new());
        socket.SendBufferSize = 1024 * 1024;
        socket.ReceiveBufferSize = 1024 * 1024;
        socket.Bind(new IPEndPoint(IPAddress.Any, 0));
        feedbackThread = new(ReceiveFeedback) { IsBackground = true, Name = "FRD UDP feedback" };
        delayedThread = new(DeliverDelayed) { IsBackground = true, Name = "FRD simulated packet delay" };
        feedbackThread.Start();
        delayedThread.Start();
    }

    public int ActualPort => ((IPEndPoint)socket.LocalEndPoint!).Port;
    public event Action<int, long, VideoSendTiming>? FrameSending;
    public void SetLimitKbps(int kbps)
    {
        if (kbps is < 1 or > 1_000_000) throw new ArgumentOutOfRangeException(nameof(kbps));
        lock (sendGate) { rateLimited = true; Volatile.Write(ref limitKbps, kbps); }
    }
    public void SetEncoderBitrateKbps(int kbps)
    {
        if (kbps is < 1 or > 1_000_000) throw new ArgumentOutOfRangeException(nameof(kbps));
        // FfmpegEncoder controls bitrate; ordinary UDP delivery does not pace against that target.
        lock (sendGate) { rateLimited = false; Volatile.Write(ref limitKbps, kbps); nextSendTick = 0; }
    }
    public void SetSimulation(NetworkSimulation value) => Volatile.Write(ref simulation, ValidateSimulation(value));

    static NetworkSimulation ValidateSimulation(NetworkSimulation value)
    {
        if (!double.IsFinite(value.CapacityMbps) || value.CapacityMbps is < 0 or > 1000 ||
            !double.IsFinite(value.LossRate) || value.LossRate is < 0 or > 1 || value.MaxDelayMs is < 0 or > 60_000)
            throw new ArgumentOutOfRangeException(nameof(value));
        return value;
    }

    public void Send(ReceivedVideo video, CancellationToken token)
    {
        ObjectDisposedException.ThrowIf(Volatile.Read(ref disposed) != 0, this);
        if (video.Data.Length is <= 0 or > VideoDatagram.MaxFrameSize)
            throw new ArgumentOutOfRangeException(nameof(video), "Encoded access units must contain 1–8388608 bytes.");
        lock (sendGate)
        {
            long firstSendTick = 0;
            double plannedWaitMs = 0, wakeupOverrunMs = 0;
            var packetCount = 0;
            for (var offset = 0; offset < video.Data.Length; offset += VideoDatagram.Payload)
            {
                token.ThrowIfCancellationRequested();
                shutdown.Token.ThrowIfCancellationRequested();
                var count = Math.Min(VideoDatagram.Payload, video.Data.Length - offset);
                var packet = new byte[VideoDatagram.Header + count];
                var seq = unchecked(++sequence);
                BinaryPrimitives.WriteUInt32LittleEndian(packet, VideoDatagram.Magic);
                packet[4] = 1;
                packet[5] = video.KeyFrame ? (byte)1 : (byte)0;
                BinaryPrimitives.WriteUInt32LittleEndian(packet.AsSpan(8), seq);
                BinaryPrimitives.WriteInt32LittleEndian(packet.AsSpan(12), video.Generation);
                BinaryPrimitives.WriteInt64LittleEndian(packet.AsSpan(16), video.FrameId);
                BinaryPrimitives.WriteInt32LittleEndian(packet.AsSpan(24), video.Data.Length);
                BinaryPrimitives.WriteInt32LittleEndian(packet.AsSpan(28), offset);
                BinaryPrimitives.WriteUInt16LittleEndian(packet.AsSpan(32), (ushort)count);
                video.Data.AsSpan(offset, count).CopyTo(packet.AsSpan(VideoDatagram.Header));
                var wait = Pace(packet.Length + 28, token);
                plannedWaitMs += wait.PlannedMs;
                wakeupOverrunMs += wait.OverrunMs;
                var now = VideoDatagram.Now;
                if (firstSendTick == 0) firstSendTick = now;
                packetCount++;
                lock (statsGate)
                {
                    stamps[seq % stamps.Length] = new(seq, now);
                    sentPackets++;
                    rates.Enqueue((now, packet.Length + 28, 0));
                    TrimRates(now);
                }
                if (offset + count == video.Data.Length)
                    FrameSending?.Invoke(video.Generation, video.FrameId, new(video.Data.Length, packetCount,
                        firstSendTick, now, plannedWaitMs, wakeupOverrunMs));
                RoutePacket(packet, destination, now);
            }
        }
    }

    public void SendDiagnostic(byte[] packet, IPEndPoint diagnosticDestination, CancellationToken token)
    {
        ObjectDisposedException.ThrowIf(Volatile.Read(ref disposed) != 0, this);
        if (packet.Length is <= 0 or > VideoDatagram.MaxSize || diagnosticDestination.AddressFamily != AddressFamily.InterNetwork || diagnosticDestination.Equals(destination))
            throw new ArgumentException("Diagnostics require a separate IPv4 destination and at most 1172 UDP payload bytes.");
        lock (sendGate)
        {
            token.ThrowIfCancellationRequested();
            shutdown.Token.ThrowIfCancellationRequested();
            Pace(packet.Length + 28, token);
            var now = VideoDatagram.Now;
            lock (statsGate)
            {
                diagnosticPackets++;
                diagnosticRates.Enqueue((now, packet.Length + 28));
                rates.Enqueue((now, packet.Length + 28, 0));
                TrimRates(now);
            }
            RoutePacket(packet, diagnosticDestination, now);
        }
    }

    void RoutePacket(byte[] packet, IPEndPoint target, long now)
    {
        var conditions = Volatile.Read(ref simulation);
        if (Random.Shared.NextDouble() < conditions.LossRate) return;
        if (conditions.MaxDelayMs == 0) SendPacket(packet, target);
        else
        {
            lock (delayGate)
            {
                if (delayed.Count >= 4096)
                {
                    VideoDatagram.Log("Simulated-delay queue full; dropping packet.");
                    return;
                }
                var due = now + (long)(Random.Shared.NextDouble() * conditions.MaxDelayMs * Stopwatch.Frequency / 1000);
                delayed.Enqueue((packet, target), due);
            }
            delayedChanged.Set();
        }
    }

    void SendPacket(byte[] packet, IPEndPoint target)
    {
        try { socket.SendTo(packet, target); }
        catch (SocketException error) when (!shutdown.IsCancellationRequested && VideoDatagram.Recoverable(error, "Video send"))
        {
            // UDP delivery failure drops this packet; subsequent packets may still succeed.
        }
    }

    (double PlannedMs, double OverrunMs) Pace(int wireBytes, CancellationToken token)
    {
        var conditions = Volatile.Read(ref simulation);
        if (!rateLimited && conditions.CapacityMbps <= 0) return (0, 0);
        var started = VideoDatagram.Now;
        var plannedTicks = Math.Max(0, nextSendTick - started);
        while (true)
        {
            token.ThrowIfCancellationRequested();
            shutdown.Token.ThrowIfCancellationRequested();
            var remainingMs = (nextSendTick - VideoDatagram.Now) * 1000 / Stopwatch.Frequency;
            if (remainingMs <= 0) break;
            var dueTime = -(long)Math.Ceiling(Math.Min(remainingMs, 20) * 10_000);
            if (!SetWaitableTimer(pacingTimer, ref dueTime, 0, 0, 0, false)) throw new Win32Exception(Marshal.GetLastWin32Error());
            if (WaitForSingleObject(pacingTimer, 100) == uint.MaxValue) throw new Win32Exception(Marshal.GetLastWin32Error());
        }
        var rate = rateLimited ? Volatile.Read(ref limitKbps) * 1000d : double.PositiveInfinity;
        if (conditions.CapacityMbps > 0) rate = Math.Min(rate, conditions.CapacityMbps * 1_000_000);
        // Carry no idle credit and no timer catch-up credit: the maximum burst is one datagram.
        var finished = VideoDatagram.Now;
        nextSendTick = finished + wireBytes * 8d * Stopwatch.Frequency / rate;
        return (plannedTicks * 1000 / Stopwatch.Frequency,
            plannedTicks > 0 ? Math.Max(0, finished - started - plannedTicks) * 1000 / Stopwatch.Frequency : 0);
    }

    void DeliverDelayed()
    {
        try
        {
            while (!shutdown.IsCancellationRequested)
            {
                (byte[] Data, IPEndPoint Destination)? packet = null;
                var waitMs = 100;
                lock (delayGate)
                {
                    if (delayed.TryPeek(out _, out var due))
                    {
                        var ms = (due - VideoDatagram.Now) * 1000d / Stopwatch.Frequency;
                        if (ms <= 0) packet = delayed.Dequeue();
                        else waitMs = Math.Clamp((int)Math.Ceiling(ms), 1, 100);
                    }
                }
                if (packet is { } ready) SendPacket(ready.Data, ready.Destination);
                else delayedChanged.WaitOne(waitMs);
            }
        }
        catch (ObjectDisposedException) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Delayed sender stopped."); }
        catch (SocketException error) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Delayed sender stopped", error); }
        catch (Exception error) { VideoDatagram.Log("Delayed sender failed", error); }
    }

    void ReceiveFeedback()
    {
        var bytes = new byte[VideoDatagram.MaxSize];
        try
        {
            while (!shutdown.IsCancellationRequested)
            {
                EndPoint peer = new IPEndPoint(IPAddress.Any, 0);
                int length;
                try
                {
                    if (!socket.Poll(100_000, SelectMode.SelectRead)) continue;
                    length = socket.ReceiveFrom(bytes, ref peer);
                }
                catch (SocketException error) when (!shutdown.IsCancellationRequested && VideoDatagram.Recoverable(error, "Feedback receive"))
                {
                    continue;
                }
                if (!destination.Equals(peer) || length != VideoDatagram.FeedbackSize || bytes[4] != 2 ||
                    BinaryPrimitives.ReadUInt32LittleEndian(bytes) != VideoDatagram.Magic) continue;
                var firstSeq = BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(8));
                var lastSeq = BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(12));
                var packetCount = BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(16));
                var wireBytes = BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(20));
                var firstReceive = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(24));
                var lastReceive = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(32));
                var frequency = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(40));
                var totalPackets = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(48));
                var totalWireBytes = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(56));
                var highestSeq = BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(64));
                if (packetCount == 0 || wireBytes == 0 || frequency <= 0 || lastReceive < firstReceive || totalPackets < 0) continue;
                var now = VideoDatagram.Now;
                lock (statsGate)
                {
                    if (totalPackets <= receivedPackets || totalPackets > sentPackets || totalWireBytes < receivedWireBytes) continue;
                    var first = stamps[firstSeq % stamps.Length];
                    var last = stamps[lastSeq % stamps.Length];
                    if (first.Sequence != firstSeq || last.Sequence != lastSeq) continue;
                    rates.Enqueue((now, 0, totalWireBytes - receivedWireBytes));
                    receivedPackets = totalPackets;
                    receivedWireBytes = totalWireBytes;
                    var receiverDelta = lastReceive - lastReceiverTick;
                    var senderDelta = last.Tick - lastSenderTick;
                    if (lastReceiverTick != 0 && receiverDelta > 0 && senderDelta > 0)
                    {
                        var receiveSeconds = (double)receiverDelta / frequency;
                        var trend = (receiveSeconds - VideoDatagram.Seconds(senderDelta)) * 1000;
                        delayTrend = .8 * delayTrend + .2 * Math.Clamp(trend, -1000, 1000);
                        var sampleSeconds = Math.Max(receiveSeconds, VideoDatagram.Seconds(senderDelta));
                        var delivered = (totalWireBytes - previousReceiverTotal) * 8 / sampleSeconds / 1_000_000;
                        if (rateLimited) delivered = Math.Min(delivered, Volatile.Read(ref limitKbps) / 1000d);
                        deliveryEstimate = deliveryEstimate == 0 ? delivered : .8 * deliveryEstimate + .2 * delivered;
                    }
                    lastReceiverTick = lastReceive;
                    lastSenderTick = last.Tick;
                    previousReceiverTotal = totalWireBytes;
                    lastFeedbackTick = now;
                    lossRate = highestSeq == 0 ? 0 : Math.Clamp(1 - (double)totalPackets / highestSeq, 0, 1);
                    TrimRates(now);
                }
            }
        }
        catch (ObjectDisposedException) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Feedback listener stopped."); }
        catch (SocketException error) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Feedback listener stopped", error); }
        catch (Exception error) { VideoDatagram.Log("Feedback listener failed", error); }
    }

    void TrimRates(long now)
    {
        while (rates.TryPeek(out var entry) && VideoDatagram.Seconds(now - entry.Time) > 1) rates.Dequeue();
        while (diagnosticRates.TryPeek(out var entry) && VideoDatagram.Seconds(now - entry.Time) > 1) diagnosticRates.Dequeue();
    }

    public NetworkSnapshot Snapshot
    {
        get
        {
            lock (statsGate)
            {
                var now = VideoDatagram.Now;
                TrimRates(now);
                var sent = rates.Sum(x => (long)x.Sent) * 8 / 1_000_000d;
                var diagnostics = diagnosticRates.Sum(x => (long)x.Bytes) * 8 / 1_000_000d;
                var videoSent = sent - diagnostics;
                var received = rates.Sum(x => x.Received) * 8 / 1_000_000d;
                var stale = lastFeedbackTick == 0 || VideoDatagram.Seconds(now - lastFeedbackTick) > 2;
                var state = videoSent <= 0 ? "idle; capacity unknown" : stale ? "awaiting feedback" :
                    videoSent < Volatile.Read(ref limitKbps) / 1000d * .8 ? "application-limited; measured lower bound" :
                    delayTrend > 2 ? "queue growing; advisory only" : "observed delivery; measured lower bound";
                return new(sent, received, stale ? 0 : deliveryEstimate, delayTrend, lossRate, sentPackets, receivedPackets, state)
                    { DiagnosticMbps = diagnostics, DiagnosticPackets = diagnosticPackets, SendBudgetKbps = rateLimited ? Volatile.Read(ref limitKbps) : 0,
                        BurstBudgetWireBytes = rateLimited ? 1200 : 0, SimulatedCapacityMbps = Volatile.Read(ref simulation).CapacityMbps };
            }
        }
    }

    public void Dispose()
    {
        if (Interlocked.Exchange(ref disposed, 1) != 0) return;
        shutdown.Cancel();
        delayedChanged.Set();
        socket.Dispose();
        feedbackThread.Join(2000);
        delayedThread.Join(2000);
        delayedChanged.Dispose();
        pacingTimer.Dispose();
        shutdown.Dispose();
    }
}

public sealed class UdpVideoReceiver : IDisposable
{
    readonly Socket socket = new(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);
    readonly CancellationTokenSource shutdown = new();
    readonly Thread receiveThread, dispatchThread;
    readonly Channel<ReceivedVideo> completed = Channel.CreateBounded<ReceivedVideo>(new BoundedChannelOptions(32)
        { SingleReader = true, SingleWriter = true, FullMode = BoundedChannelFullMode.Wait });
    readonly Dictionary<(int Generation, long Frame), Assembly> frames = new();
    readonly uint[] seen = new uint[65536];
    readonly bool[] seenValid = new bool[65536];
    EndPoint? source;
    IPEndPoint? expectedSource;
    long bufferedBytes, queuedBytes, totalPackets, totalWireBytes, firstReceiveTick, lastReceiveTick, feedbackTick;
    uint firstSequence, lastSequence, highestSequence, batchPackets, batchWireBytes;
    int disposed, currentGeneration = int.MinValue;

    sealed class Assembly(int total, bool keyFrame)
    {
        public readonly byte[] Data = new byte[total];
        public readonly bool[] Fragments = new bool[(total + VideoDatagram.Payload - 1) / VideoDatagram.Payload];
        public readonly bool KeyFrame = keyFrame;
        public readonly long Created = VideoDatagram.Now;
        public int Count;
    }

    public UdpVideoReceiver(int port = 0)
    {
        socket.Bind(new IPEndPoint(IPAddress.Any, port));
        socket.ReceiveBufferSize = 1024 * 1024;
        receiveThread = new(Receive) { IsBackground = true, Name = "FRD UDP receive and feedback" };
        dispatchThread = new(Dispatch) { IsBackground = true, Name = "FRD decoded-stream dispatch" };
        receiveThread.Start();
        dispatchThread.Start();
    }

    public int Port => ((IPEndPoint)socket.LocalEndPoint!).Port;
    public event Action<ReceivedVideo>? VideoReceived;
    public void SetExpectedSource(IPEndPoint endpoint) => Volatile.Write(ref expectedSource, endpoint);

    void Receive()
    {
        var bytes = new byte[65536];
        try
        {
            while (!shutdown.IsCancellationRequested)
            {
                EndPoint peer = new IPEndPoint(IPAddress.Any, 0);
                int length;
                try
                {
                    if (!socket.Poll(20_000, SelectMode.SelectRead))
                    {
                        FlushFeedback();
                        ExpireFrames();
                        continue;
                    }
                    length = socket.ReceiveFrom(bytes, ref peer);
                    if (Volatile.Read(ref expectedSource) is { } expected && !expected.Equals(peer)) continue;
                }
                catch (SocketException error) when (!shutdown.IsCancellationRequested && VideoDatagram.Recoverable(error, "Video receive"))
                {
                    continue;
                }
                var now = VideoDatagram.Now;
                if (length < VideoDatagram.Header || length > VideoDatagram.MaxSize || bytes[4] != 1 || bytes[5] > 1 ||
                    BinaryPrimitives.ReadUInt32LittleEndian(bytes) != VideoDatagram.Magic) continue;
                var seq = BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(8));
                var generation = BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(12));
                var frameId = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(16));
                var total = BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(24));
                var offset = BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(28));
                var count = BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(32));
                if (total is <= 0 or > VideoDatagram.MaxFrameSize || offset < 0 || offset >= total ||
                    offset % VideoDatagram.Payload != 0 || count != Math.Min(VideoDatagram.Payload, total - offset) ||
                    length != VideoDatagram.Header + count) continue;
                if (source is not null && !source.Equals(peer)) continue;
                source ??= peer;
                var slot = seq % seen.Length;
                if (seenValid[slot] && seen[slot] == seq) continue;
                if (totalPackets > 0 && unchecked((int)(seq - highestSequence)) < -seen.Length) continue;
                seen[slot] = seq;
                seenValid[slot] = true;
                if (totalPackets == 0 || unchecked((int)(seq - highestSequence)) > 0) highestSequence = seq;
                if (batchPackets == 0) { firstSequence = seq; firstReceiveTick = now; }
                lastSequence = seq;
                lastReceiveTick = now;
                batchPackets++;
                batchWireBytes += (uint)(length + 28);
                totalPackets++;
                totalWireBytes += length + 28;
                if (generation < currentGeneration) { MaybeFlushFeedback(now); continue; }
                if (generation > currentGeneration)
                {
                    frames.Clear();
                    bufferedBytes = 0;
                    currentGeneration = generation;
                }
                ExpireFrames();
                var key = (generation, frameId);
                if (!frames.TryGetValue(key, out var frame))
                {
                    while (frames.Count >= 32 || bufferedBytes + total > VideoDatagram.MaxBufferedBytes)
                    {
                        var oldest = frames.MinBy(x => x.Value.Created);
                        bufferedBytes -= oldest.Value.Data.Length;
                        frames.Remove(oldest.Key);
                    }
                    frame = new(total, bytes[5] == 1);
                    frames.Add(key, frame);
                    bufferedBytes += total;
                }
                if (frame.Data.Length != total || frame.KeyFrame != (bytes[5] == 1)) { MaybeFlushFeedback(now); continue; }
                var index = offset / VideoDatagram.Payload;
                if (!frame.Fragments[index])
                {
                    bytes.AsSpan(VideoDatagram.Header, count).CopyTo(frame.Data.AsSpan(offset));
                    frame.Fragments[index] = true;
                    frame.Count++;
                }
                if (frame.Count == frame.Fragments.Length)
                {
                    var reassembledTick = VideoDatagram.Now;
                    frames.Remove(key);
                    bufferedBytes -= total;
                    FlushFeedback();
                    var queued = Interlocked.Add(ref queuedBytes, total);
                    if (queued > VideoDatagram.MaxBufferedBytes || !completed.Writer.TryWrite(new(generation, frameId, frame.KeyFrame, frame.Data)
                        { ReassembledTick = reassembledTick }))
                    {
                        Interlocked.Add(ref queuedBytes, -total);
                        VideoDatagram.Log($"Decoder dispatch queue full; dropped access unit {generation}/{frameId}.");
                    }
                }
                else MaybeFlushFeedback(now);
            }
        }
        catch (ObjectDisposedException) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Receiver stopped."); }
        catch (SocketException error) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Receiver stopped", error); }
        catch (Exception error) { VideoDatagram.Log("Receiver failed", error); }
        finally { completed.Writer.TryComplete(); }
    }

    void MaybeFlushFeedback(long now)
    {
        if (VideoDatagram.Seconds(now - feedbackTick) >= .02) FlushFeedback();
    }

    void FlushFeedback()
    {
        if (batchPackets == 0 || source is null) return;
        Span<byte> bytes = stackalloc byte[VideoDatagram.FeedbackSize];
        bytes.Clear();
        BinaryPrimitives.WriteUInt32LittleEndian(bytes, VideoDatagram.Magic);
        bytes[4] = 2;
        BinaryPrimitives.WriteUInt32LittleEndian(bytes[8..], firstSequence);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes[12..], lastSequence);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes[16..], batchPackets);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes[20..], batchWireBytes);
        BinaryPrimitives.WriteInt64LittleEndian(bytes[24..], firstReceiveTick);
        BinaryPrimitives.WriteInt64LittleEndian(bytes[32..], lastReceiveTick);
        BinaryPrimitives.WriteInt64LittleEndian(bytes[40..], Stopwatch.Frequency);
        BinaryPrimitives.WriteInt64LittleEndian(bytes[48..], totalPackets);
        BinaryPrimitives.WriteInt64LittleEndian(bytes[56..], totalWireBytes);
        BinaryPrimitives.WriteUInt32LittleEndian(bytes[64..], highestSequence);
        try { socket.SendTo(bytes, SocketFlags.None, source); }
        catch (SocketException error) when (!shutdown.IsCancellationRequested && VideoDatagram.Recoverable(error, "Feedback send"))
        {
            // The next feedback carries cumulative counters, so losing this batch is recoverable.
        }
        batchPackets = batchWireBytes = 0;
        feedbackTick = VideoDatagram.Now;
    }

    void ExpireFrames()
    {
        var now = VideoDatagram.Now;
        foreach (var key in frames.Where(x => VideoDatagram.Seconds(now - x.Value.Created) > 2).Select(x => x.Key).ToArray())
        {
            bufferedBytes -= frames[key].Data.Length;
            frames.Remove(key);
        }
    }

    void Dispatch()
    {
        try
        {
            while (completed.Reader.WaitToReadAsync(shutdown.Token).AsTask().GetAwaiter().GetResult())
                while (completed.Reader.TryRead(out var video))
                {
                    Interlocked.Add(ref queuedBytes, -video.Data.Length);
                    try { VideoReceived?.Invoke(video); }
                    catch (Exception error) { VideoDatagram.Log("Video callback failed", error); }
                }
        }
        catch (OperationCanceledException) when (shutdown.IsCancellationRequested) { VideoDatagram.Log("Video dispatch stopped."); }
    }

    public void Dispose()
    {
        if (Interlocked.Exchange(ref disposed, 1) != 0) return;
        shutdown.Cancel();
        socket.Dispose();
        receiveThread.Join(2000);
        completed.Writer.TryComplete();
        if (Thread.CurrentThread != dispatchThread && !dispatchThread.Join(2000))
            VideoDatagram.Log("Video callback is still finishing after receiver shutdown.");
        shutdown.Dispose();
    }
}

